begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":498,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":0,"options":["$(C)$ đứng yên, nam châm chuyển động xuống dưới.","$(C)$ và nam châm cùng chuyển động đều lên trên cùng vận tốc.","$(C)$ và nam châm cùng chuyển động đều xuống dưới cùng vận tốc.","$(C)$ và nam châm cùng đứng yên."],"question":"Bố trí nam châm và mạch kín $(C)$ như hình vẽ. Từ thông qua vòng dây dẫn $(C)$ biến thiên khi <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig20.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<em>Từ thông qua vòng dây dẫn biến thiên khi vòng dây và nam châm chuyển động tương đối với nhau.</em>","distractorNotes":{"B":"Nhầm chuyển động cùng vận tốc với chuyển động tương đối: vị trí tương đối giữa nam châm và vòng dây không đổi.","C":"Chỉ thấy có chuyển động mà quên xét chuyển động tương đối: hai vật cùng vận tốc thì từ thông giữ nguyên.","D":"Bỏ sót điều kiện từ thông biến thiên: không có chuyển động tương đối thì $\\Phi$ không đổi, không có chuyển động nào cả."},"difficultySource":null},"ex":[]},{"id":499,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["bị làm cho vòng dây biến dạng.","quay xung quanh pháp tuyến của nó.","dịch chuyển tịnh tiến dọc theo đường sức từ.","quay xung quanh một trục trùng với đường sức từ."],"question":"Một vòng dây dẫn được đặt trong một từ trường đều, sao cho mặt phẳng của vòng dây vuông góc với các đường sức từ. Hiện tượng cảm ứng điện từ xảy ra khi vòng dây <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig21.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<em>Khi vòng dây bị làm cho biến dạng, diện tích vòng dây thay đổi nên từ thông sẽ thay đổi $\\to$ xảy ra hiện tượng cảm ứng điện từ.</em>","distractorNotes":{"B":"Quay quanh pháp tuyến giữ nguyên góc $\\alpha$ giữa $\\vec{B}$ và $\\vec{n}$, diện tích không đổi nên $\\Phi$ không đổi.","C":"Tịnh tiến dọc đường sức trong từ trường đều: $B$, $S$, $\\alpha$ đều không đổi nên $\\Phi$ không đổi.","D":"Trục quay trùng đường sức thì mặt phẳng vòng dây vẫn vuông góc với $\\vec{B}$, góc $\\alpha$ không đổi."},"difficultySource":null},"ex":[]},{"id":506,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Từ thông qua khung dây","answer":0,"options":["4.","2.","1.","3."],"question":"Trong hình vẽ nào sau đây, từ thông gửi qua diện tích của khung dây dẫn có giá trị <strong>lớn nhất</strong>? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig22.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<em>Hình 4 có số đường sức từ xuyên qua diện tích của khung dây dẫn nhiều nhất nên có từ thông lớn nhất.</em>","distractorNotes":{"B":"Chưa so sánh số đường sức xuyên qua khung giữa các hình: hình 2 có ít đường sức xuyên qua hơn.","C":"Chưa đếm số đường sức xuyên qua khung ở các hình: hình 1 có từ thông nhỏ hơn hình có nhiều đường sức nhất.","D":"Bỏ sót việc xét góc giữa đường sức và mặt khung: hình 3 có số đường sức xuyên qua chưa nhiều nhất."},"difficultySource":null},"ex":[]},{"id":509,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["là chiều dương quy ước trên hình.","ngược với chiều dương quy ước trên hình.","ngược với chiều dương quy ước khi nam châm ở phía trên vòng dây và chiều ngược lại khi nam châm ở phía dưới.","là chiều dương quy ước khi nam châm ở phía trên vòng dây và chiều ngược lại khi nam châm ở phía dưới."],"question":"Cho một nam châm thẳng rơi theo phương thẳng đứng qua tâm <em>O</em> của vòng dây dẫn tròn nằm ngang như hình vẽ. Trong quá trình nam châm rơi, vòng dây xuất hiện dòng điện cảm ứng có chiều <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig74.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>+ Khi cực N của nam châm tiến lại gần vòng dây thì từ thông tăng lên $\\to$ vòng dây xuất hiện dòng điện cảm ứng sao cho từ trường của nó</em> $\\vec{B_c} \\uparrow\\downarrow \\vec{B}$ <em>$\\to$ có chiều hướng lên. Áp dụng quy tắc nắm bàn tay phải, ta xác định được chiều của i</em>$_{C}$ <em>là ngược chiều dương quy ước trên hình.</em> <em>+ Hiện tượng ngược lại khi nam châm xuyên qua và cực S rời xa vòng dây, i</em>$_{C}$ <em>có chiều ngược lại.</em>","distractorNotes":{"A":"Chỉ xét một giai đoạn nam châm tiến lại gần, quên rằng khi nam châm đi qua và rời xa thì chiều dòng điện đổi.","B":"Chỉ xét giai đoạn nam châm đang tiến lại gần, bỏ sót giai đoạn nam châm rời xa làm từ thông giảm.","D":"Đổi ngược chiều: khi từ thông tăng, từ trường cảm ứng ngược chiều từ trường ngoài, rồi áp dụng quy tắc nắm tay phải sai chiều."},"difficultySource":null},"ex":[]},{"id":512,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["từ trường của nam châm đang tăng đều.","nam châm đang rời xa cuộn dây.","nam châm đang đứng yên.","nam châm đang đến gần cuộn dây."],"question":"Dòng điện cảm ứng $I_c$ trong vòng dây có chiều như hình vẽ, lúc này <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig23.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Dựa vào chiều của dòng điện trong vòng dây ta dùng quy tắc nắm tay phải xác định được chiều của</em> $\\vec{B}'$ <em>cùng chiều</em> $\\vec{B},$ <em>do đó từ thông qua vòng dây giảm, nên nam châm đang rời xa vòng dây.</em>","distractorNotes":{"B":"Nhầm hiện tượng nam châm đến gần với rời xa, hiểu ngược xu hướng thay đổi của từ thông qua vòng dây.","C":"Lẫn nam châm đứng yên với có dòng điện: từ thông không đổi thì không có dòng cảm ứng.","D":"Xác định ngược chiều $\\vec{B}'$ so với $\\vec{B}$: từ thông tăng thì $\\vec{B}'$ ngược chiều $\\vec{B}$."},"difficultySource":null},"ex":[]},{"id":516,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["Hình 1 và Hình 2.","Hình 1 và Hình 3.","Hình 2 và Hình 4.","Hình 4 và Hình 3."],"question":"Chiều dòng điện cảm ứng trong vòng dây đúng là <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig75.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khi nam châm hoặc vòng đây chuyển động ra xa nhau thì mặt từ bên trái của vòng dây là mặt N, nên chiều i</em>$_{C}$ <em>được xác định theo quy tắc nắm tay phải có chiều như hình 1 và 3.</em>","distractorNotes":{"B":"Chọn Hình 1 và 3 theo mặt từ chung, bỏ sót việc kiểm tra từng hình theo loại chuyển động.","C":"Ghép Hình 2 với Hình 4 mà không xét từ thông tăng hay giảm, nên chiều dòng điện sai.","D":"Nhầm chiều dòng điện cảm ứng ở các hình này: không xác định đúng mặt N, S của vòng dây."},"difficultySource":null},"ex":[]},{"id":517,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":3,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng chạy theo chiều dương hoặc chiều âm."],"question":"Một vòng dây dẫn kín, tròn, phẳng không biến dạng (<em>C</em>) đặt trong mặt phẳng song song với mặt phẳng <em>Oxz</em>, một nam châm thẳng (<em>NS</em>) đặt song song với trục <em>Oy</em> và chiều dương trên (<em>C</em>) như hình vẽ. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig76.png\" alt=\"Hình minh họa\"> Nếu cho (<em>NS</em>) quay đều quanh trục quay song song với trục <em>Ox</em> thì trong (<em>C</em>)","difficulty":"trung-binh","explanation":"<em>Nếu cho (NS) quay đều quanh trục quay song song với trục Ox thì từ thông qua (C) biến thiên tuần hoàn nên trong (C) sẽ có dòng điện i</em>$_{c}$ <em>xoay chiều.</em>","distractorNotes":{"A":"Cho rằng nam châm quay thì từ thông không đổi, bỏ qua sự biến thiên tuần hoàn của từ thông.","B":"Chỉ xét một nửa chu kỳ quay, quên rằng từ thông lúc tăng lúc giảm nên dòng đổi chiều.","C":"Chỉ xét một nửa chu kỳ quay, quên rằng từ thông lúc tăng lúc giảm nên dòng đổi chiều."},"difficultySource":null},"ex":[]},{"id":519,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":1,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương.","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng với cường độ biến thiên tuần hoàn theo thời gian."],"question":"Một thanh nam châm <em>NS</em> được đặt thẳng đứng song song với mặt phẳng chứa vòng dây dẫn (<em>C</em>) và có trục quay <em>O</em> vuông góc với trục của vòng dây, chiều dương trên vòng dây được chọn như hình vẽ. Thanh nam châm <em>NS</em> chuyển động quay góc 90$^\\circ$ để cực Nam (<em>S</em>) của nó tới đối diện với vòng dây dẫn (<em>C</em>) thì trong (<em>C</em>) <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig78.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khi cực Nam (S) của nam châm quay 90</em>$^\\circ$ <em>tới đối diện với vòng dây dẫn (C) thì trong (C) xuất hiện dòng i</em>$_{C}$ <em>sao cho mặt từ bên phải vòng dây là mặt S. Áp dụng quy tắc nắm tay phải ta xác định được chiều i</em>$_{C}$ <em>có chiều theo chiều dương quy ước.</em>","distractorNotes":{"A":"Bỏ qua việc từ thông qua vòng dây thay đổi khi nam châm quay từ vị trí song song sang đối diện.","C":"Đảo chiều: xác định sai mặt từ của vòng dây hoặc áp dụng nắm tay phải ngược chiều.","D":"Lẫn quay 90° một lần với quay liên tục: dòng cảm ứng chỉ xuất hiện trong lúc từ thông biến thiên."},"difficultySource":null},"ex":[]},{"id":520,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":3,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng với cường độ biến thiên theo thời gian."],"question":"Một thanh nam châm <em>NS</em> được đặt thẳng đứng song song với mặt phẳng chứa vòng dây dẫn (<em>C</em>) và có trục quay <em>O</em> vuông góc với trục của vòng dây, chiều dương hên vòng dây được chọn như hình vẽ. Thanh nam châm <em>NS</em> chuyển động quay đều quanh trục qua <em>O</em> của nó thì trong (<em>C</em>) <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig79.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Thanh nam châm NS chuyển động quay đều quanh trục qua O của nó thì trong (C) có dòng điện cảm ứng với cường độ biến thiên theo thời gian.</em>","distractorNotes":{"A":"Quên rằng khi nam châm quay đều, từ thông qua vòng dây biến thiên liên tục nên luôn có dòng cảm ứng.","B":"Cho rằng dòng cảm ứng chỉ một chiều, bỏ qua việc từ thông tăng giảm làm chiều dòng điện đổi luân phiên.","C":"Cho rằng dòng cảm ứng chỉ một chiều, bỏ qua việc từ thông tăng giảm làm chiều dòng điện đổi luân phiên."},"difficultySource":null},"ex":[]},{"id":521,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":1,"options":["lại gần khung dây thì thấy khung dây chuyển động theo chiều dương trục.","lại gần khung dây thì thấy khung dây chuyển động theo chiều âm trục $x'x$.","ra xa khung dây thì thấy khung dây chuyển động theo chiều âm trục $x'x$.","thì chúng luôn đẩy khung dây."],"question":"Một khung dây dẫn tròn, nhẹ, được heo bằng sợi dây mềm, đường thẳng $x'x$ trùng với trục của khung dây, một nam châm thẳng đặt dọc theo trục $x'x$, cực Bắc của nam châm gần khung dây như hình vẽ. Tịnh tiến nam châm <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig35.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Thanh nam châm NS tịnh tiến lại gần khung dây thì thấy nam châm sẽ gây ra dòng điện cảm ừng trong khung dây, dòng điện này sẽ chống lại nguyên nhân sinh ra nó tức là chuyển động theo chiều âm trục x'x.</em>","distractorNotes":{"A":"Áp dụng định luật Len-xơ ngược: cho khung bị hút theo nam châm thay vì chống lại sự tăng từ thông.","C":"Lẫn nam châm ra xa với lại gần: ra xa thì từ thông giảm, khung bị hút theo, không bị đẩy.","D":"Khái quát sai: nam châm ra xa thì khung bị hút, chỉ khi lại gần mới bị đẩy."},"difficultySource":null},"ex":[]},{"id":522,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["trong khung dây không có dòng điện cảm ứng.","trong khung dây xuất hiện dòng điện cảm ứng có chiều <em>ABCD</em>.","khung dây bị đẩy ra xa nam châm.","khung dây bị hút lại gần nam châm."],"question":"Một khung dây dẫn rất nhẹ được treo bằng sợi dây mềm, đường thẳng $x'x$ trùng với trục của khung dây. Khung dây được đặt gần một nam châm điện, trục nam châm điện trùng với trục $x'x.$ Khi cho con chạy của biến trở dịch chuyển từ <em>M</em> đến <em>N</em> thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig80.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khi cho con chạy của biến trở dịch chuyển từ M đến N thì thì từ thông qua khung dây tăng thì thấy nam châm điện sẽ gây ra dòng điện cảm ừng trong khung dây, dòng điện này sẽ chống lại nguyên nhân sinh ra nó tức là khung dây bị đẩy ra xa nam châm.</em>","distractorNotes":{"A":"Bỏ sót việc dòng qua nam châm điện thay đổi làm từ thông qua khung biến thiên nên có dòng cảm ứng.","B":"Xác định sai chiều dòng cảm ứng: nhầm chiều từ trường cảm ứng cần chống lại sự tăng từ thông.","D":"Hiểu ngược định luật Len-xơ: từ thông tăng thì khung chống lại bằng cách đẩy, không phải hút."},"difficultySource":null},"ex":[]},{"id":523,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương.","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng biến thiên."],"question":"Một khung dây dẫn tròn gồm <em>N</em> vòng. Khung nằm trong từ trường đều, mặt phẳng khung song song với đường sức từ, chiều dương của khung như hình vẽ. Cho khung quay xung quanh trục <em>MN</em>, qua tâm của khung và trùng với một đường sức từ thì trong khung dây tròn <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig36.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khung quay xung quanh trục MN đi qua tâm của khung và trùng với một đường sức từ thì từ thông luôn bằng không hay không có dòng điện cảm ứng.</em>","distractorNotes":{"B":"Bỏ sót việc xét từ thông: trục quay trùng đường sức nên từ thông luôn bằng 0, không có dòng cảm ứng.","C":"Bỏ sót việc xét từ thông: trục quay trùng đường sức nên từ thông luôn bằng 0, không có dòng cảm ứng.","D":"Nhầm khung quay với từ thông biến thiên: mặt phẳng khung luôn song song đường sức nên $\\Phi=0$ không đổi."},"difficultySource":null},"ex":[]},{"id":524,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng biến thiên."],"question":"Cho dòng điện thẳng cường độ <em>I</em> không đổi và khung dây dẫn hình chữ nhật <em>MNPQ</em>, cạnh <em>MQ</em> của khung sát với dòng điện như hình vẽ. Cho biết các dây dẫn đều có lớp vỏ cách điện. Cho khung dây dẫn quay xung quanh cạnh <em>MQ</em> của khung thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig37.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Cho khung dây dẫn quay xung quanh cạnh MQ (do khung sát với dòng điện) thì từ thông luôn không đổi hay không có dòng điện cảm ứng.</em>","distractorNotes":{"B":"Quên xét từ thông: quay quanh cạnh MQ sát dòng điện thì từ thông không đổi, nên không có dòng cảm ứng.","C":"Quên xét từ thông: quay quanh cạnh MQ sát dòng điện thì từ thông không đổi, nên không có dòng cảm ứng.","D":"Nhầm khung quay với từ thông biến thiên: ở đây từ thông luôn không đổi nên dòng cảm ứng bằng 0."},"difficultySource":null},"ex":[]},{"id":525,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo <em>MNPQ.</em>","có dòng điện cảm ứng chạy theo <em>NMQP</em>.","có dòng điện cảm ứng thay đổi tuần hoàn."],"question":"Cho dòng điện thẳng cường độ <em>I</em> không đổi. Khung dây dẫn hình chữ nhật <em>MNPQ</em> được đặt gần dòng điện, cạnh <em>MQ</em> của khung song song với dòng điện như hình vẽ. Cho khung dây dẫn quay đều xung quanh cạnh <em>MQ</em> thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig38.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Khung dây dẫn quay đều xung quanh cạnh MQ thì trong khung MNPQ có dòng điện cảm ứng thay đổi tuần hoàn.</em>","distractorNotes":{"A":"Bỏ sót sự biến thiên từ thông: khung quay quanh MQ song song dòng điện làm từ thông thay đổi.","B":"Xác định ngược chiều dòng cảm ứng: áp dụng sai định luật Len-xơ hoặc quy tắc nắm tay phải.","D":"Lẫn dòng thay đổi tuần hoàn với chiều cần xác định: khung quay đều nên chiều dòng điện đổi."},"difficultySource":null},"ex":[]},{"id":526,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["chiều của dòng điện cảm ứng xuất hiện trong khung dây là <em>ABCD</em>.","chiều của dòng điện cảm ứng xuất hiện trong khung dây là <em>ADCB</em>.","trong khung dây không có dòng điện cảm ứng.","dòng điện cảm ứng trong khung dây luôn được duy trì cho dù con chạy dừng lại."],"question":"Cho một ống dây quấn trên lõi thép có dòng điện chạy qua đặt gần một khung dây kín <em>ABCD</em> như hình vẽ. Cường độ dòng điện trong ông dây có thể thay đổi được nhờ biến trở có có con chạy <em>R</em>. Nếu dịch chuyển con chạy của biến trở từ <em>M</em> về phía <em>N</em> thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig39.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khi cho con chạy của biến trở dịch chuyển từ M đến N thì thì từ thông qua khung dây tăng thì thấy nam châm điện sẽ gây ra dòng điện cảm ừng trong khung dây, dòng điện này sẽ chống lại nguyên nhân sinh ra nó theo định luật Len xơ sẽ có chiều ABCD.</em>","distractorNotes":{"B":"Đảo chiều: áp dụng Len-xơ ngược, cho rằng dòng cảm ứng làm tăng thêm từ thông tăng.","C":"Bỏ sót việc con chạy dịch chuyển làm dòng điện đổi, từ thông qua khung biến thiên nên có dòng cảm ứng.","D":"Lẫn dòng cảm ứng với dòng không đổi: con chạy dừng thì từ thông không đổi nên dòng cảm ứng mất."},"difficultySource":null},"ex":[]},{"id":528,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương.","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng với biến thiên tuần hoàn theo thời gian."],"question":"Một vòng dây dẫn kín $(C)$ được đặt đối diện với đầu của ống dây dẫn <em>L</em> hình trụ mắc trong mạch điện, hiều dương trên $(C)$ được chọn như hình vẽ. Nếu cho $(C)$ dịch chuyển xa <em>L</em> thì trong $(C)$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig41.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Khi (C) di chuyển ra xa L thì từ thông qua (C) giảm, theo định luật Lenxơ trong (C) xuất hiện dòng cảm ứng chống lại sự giảm đó, dòng cảm ứng sinh ra từ trường có cảm ứng từ hướng ra xa L. Áp dụng quy tắc nắm tay phải, dòng điện trong (C) chạy theo chiều dương.</em>","distractorNotes":{"A":"Quên rằng khi vòng dây ra xa ống dây, từ thông qua $(C)$ giảm nên có suất điện động cảm ứng.","C":"Đảo chiều dòng cảm ứng: từ thông giảm nhưng lại cho từ trường cảm ứng ngược chiều từ trường gốc.","D":"Lẫn với dòng xoay chiều: dịch chuyển một chiều chỉ làm từ thông biến thiên một hướng, không tuần hoàn."},"difficultySource":null},"ex":[]},{"id":529,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo chiều dương.","có dòng điện cảm ứng chạy theo chiều âm.","có dòng điện cảm ứng biến thiên tuần hoàn theo thời gian."],"question":"Một vòng dây dẫn kín $(C)$ được đặt đối diện với đầu của ống dây dẫn <em>L</em> hình trụ mắc trong mạch điện, hiều dương trên $(C)$ được chọn như hình vẽ. Nếu cho giá trị của biến trở <em>R</em> tăng dần thì trong $(C)$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig42.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Áp dụng công thức định luật Ohm cho toàn mạch</em> $I = \\frac{\\xi}{R + r}$ <em>, ta thấy khi R tăng thì I giảm. Do đó, hiệu điện thế U giữa hai đầu ống dây L (bằng hiệu điện thế giữa hai cực của nguồn điện E) tăng, nên dòng điện I</em>$_{1}$ <em>chạy qua ống dây L tăng và từ thông qua vòng dây dẫn (C) tăng theo.</em> <em>Theo định luật Lenz, dòng điện cảm ứng i</em>$_{C}$ <em>xuất hiện trong vòng dây dẫn (C) phải có chiều sao cho từ trường cảm ứng của dòng ic có tác dụng chống lại sự tăng từ thông qua nó, tức là các đường sức từ của dòng ic phải ngược chiều với các đường sức từ của ống dây L. Như vậy, chiều dòng điện cảm ứng ic trong vòng dây dẫn (C) ngược với chiều dương đã chọn.</em>","distractorNotes":{"A":"Bỏ sót bước: đổi biến trở làm dòng qua ống dây thay đổi, từ thông qua $(C)$ biến thiên.","B":"Áp dụng sai định luật Len-xơ: từ trường cảm ứng phải chống lại sự biến thiên, không cùng chiều.","D":"Lẫn với dòng xoay chiều: biến trở tăng đơn điệu nên từ thông biến thiên một chiều, không tuần hoàn."},"difficultySource":null},"ex":[]},{"id":530,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["không có dòng điện cảm ứng.","có dòng điện cảm ứng chạy theo <em>MNPQ</em>.","có dòng điện cảm ứng chạy theo <em>NMQP</em>.","có dòng điện cảm ứng biến thiên tuần hoàn theo thời gian."],"question":"Một khung dây dẫn hình chữ nhật <em>MNPQ</em> đặt trong cùng một mặt phẳng với một mạch điện như hình vẽ. Khoá <em>K</em> đang đóng, sau đó dịch chuyển con chạy <em>C</em> về phía bên phải (phía khung dây <em>MNPQ</em>) thì trong khung dây <em>MNPQ</em> <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig43.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Áp dụng quy tắc nắm tay phải, cảm ứng từ</em> $\\vec{B}$ <em>của dòng điện trong mạch gây ra trên khung MNPQ hướng từ ngoài vào trong mặt phẳng hình vẽ.</em> <em>Gọi R</em>$_{X}$ <em>là phần điện trở bên trái con chạy C của biến trở, khi đó điện trở tương đương mạch ngoài</em> $R_N = \\frac{R_1 R_x}{R_1 + R_x} + (R - R_x)$ = $R - \\frac{R_x^2}{R_1 + R_x} = R - \\frac{1}{\\frac{R_1}{R_x^2} + \\frac{1}{R_x}}$. <em>Khi C chạy về bên phải thì R</em>$_{X}$ <em>tăng nên R</em>$_{N}$ <em>giảm, dòng điện chạy trong mạch tăng do đó từ thông qua khung dây dẫn MNPQ tăng theo. Theo định luật Len-xơ, dòng điện cảm ứng xuất hiện trong khung dây dẫn MNPQ phải có chiều MNPQ sao cho từ trường cảm ứng của nó ngược hướng với từ trường</em> $\\vec{B}$ <em>, chống lại sự tăng từ thông qua khung dây MNPQ.</em>","distractorNotes":{"A":"Bỏ sót bước: con chạy dịch làm điện trở mạch đổi, dòng điện và từ thông qua khung biến thiên.","C":"Đảo chiều dòng cảm ứng: nhầm từ trường cảm ứng cùng chiều với từ trường gốc khi từ thông tăng.","D":"Lẫn dòng cảm ứng với dòng xoay chiều: dịch con chạy một hướng chỉ làm từ thông biến thiên một hướng."},"difficultySource":null},"ex":[]},{"id":531,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["ở ngoài vùng <em>MNPQ</em>.","ở trong vùng <em>MNPQ</em>.","từ ngoài vào trong vùng <em>MNPQ</em>.","đến gần vùng <em>MNPQ</em>."],"question":"Khung dây dẫn phẳug <em>ABCD</em> nằm trong mặt phẳng hình vẽ, trong từ trường đều vuông góc với mặt phẳng hình vẽ. Coi rằng bên ngoài vùng <em>MNPQ</em> không có từ trường. Khung chuyển động thẳng đều dọc theo hai đường thẳng song song $x'x,$ $y'y$ trong mặt phẳng hình vẽ. Trong khung sẽ xuất hiện dòng điện cảm ứng khi khung đang chuyển động <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig81.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Trong khung sẽ xuất hiện dòng điện cảm ứng khi khung đang chuyển động ở ngoài vào trong vùng MNPQ vì khi đó từ thông qua khung biến thiên.</em>","distractorNotes":{"A":"Bỏ sót điều kiện: ngoài vùng không có từ trường nên từ thông luôn bằng 0, không biến thiên.","B":"Quên rằng trong từ trường đều, khung tịnh tiến giữ nguyên số đường sức xuyên qua nên từ thông không đổi.","D":"Nhầm khung gần vùng từ trường với khung đã vào: chưa vào thì từ thông vẫn bằng 0, không đổi."},"difficultySource":null},"ex":[]},{"id":533,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":0,"options":["nhanh dần rồi chuyển động thẳng đều.","chậm dần rồi chuyển động thẳng đều.","nhanh dần rồi chậm dần rồi dừng lại.","đều mãi mãi."],"question":"Cho thanh dẫn điện <em>MN</em> đặt nằm ngang trên hai thanh ray dẫn điện $x'x,$ $y'y$ như trên hình vẽ. Hai thanh ray đủ dài được đặt trong từ trường đều đủ rộng, hướng vuông góc với mặt phẳng chứa hai thanh. Lúc đầu thanh <em>MN</em> đứng yên. Tác dụng lên thanh <em>MN</em> lực <em>F</em> không đổi hướng về bên trái (phía <em>x</em>'<em>y</em>') làm cho <em>MN</em> chuyển động. Giả thiết điện trở của thanh <em>MN</em> và hai thanh ray rất nhỏ, ma sát giữa <em>MN</em> và hai thanh ray rất nhỏ thì thanh chuyển động thẳng <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig44.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Lúc đầu dưới tác dụng của lực F thanh MN chuyển động có gia tố</em><strong>C.</strong> <em>Vận tốc càng tăng thì lực từ tác dụng lên MN cũng càng tăng. Dòng điện cảm ứng trong thanh MN có chiều từ M sang N, vì vậy chiều của lực từ ngược với chiều của lực từ ngoài tác dụng lên MN. Do hai thanh đủ dài nên cuối cùng lực từ cân bằng với lực ngoài. Từ lúc đó thanh MN chuyển động đều.</em>","distractorNotes":{"B":"Quên lúc đầu $v=0$ nên lực từ bằng 0, lực $F$ phải làm thanh nhanh dần trước, không chậm dần.","C":"Tưởng lực từ có thể vượt $F$ làm thanh dừng; thực ra lực từ chỉ tăng đến khi cân bằng $F$.","D":"Bỏ sót giai đoạn đầu: lúc $v=0$ chưa có lực từ nên $F$ gây gia tốc, chưa chuyển động đều được."},"difficultySource":null},"ex":[]},{"id":536,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["là một hằng số.","hàm bậc nhất theo thời gian.","hàm bậc hai theo thời gian.","hàm sin theo thời gian."],"question":"Đồ thị bên biểu diễn suất điện động cảm ứng qua một mạch điện theo thời gian. Từ thông qua mạch điện là <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig45.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<em>Từ thông qua mạch điện là hàm bậc nhất theo thời gian. Vì sau khi tính</em> $e_c = \\frac{\\Delta\\Phi}{\\Delta t} \\notin t$","distractorNotes":{"B":"Lẫn đồ thị của $e$ với đồ thị của $\\Phi$: $\\Phi$ bậc nhất thì $e$ là hằng số khác không.","C":"Nhầm dạng hàm: $e=-\\Delta\\Phi/\\Delta t$ là đạo hàm của $\\Phi$, nên $\\Phi$ bậc hai làm $e$ bậc nhất theo $t$.","D":"Cho $e$ và $\\Phi$ cùng dạng sin: quên rằng $e$ lấy đạo hàm của $\\Phi$ nên dạng đồ thị phải khớp."},"difficultySource":null},"ex":[]},{"id":541,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":0,"options":["đẩy nhau.","hút nhau.","cả hút và đẩy.","không tương tác."],"question":"Tương tác giữa hai đoạn dây thẳng <em>MN</em> và <em>PQ</em> ở hình vẽ bên là <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig46.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Dòng điện I có chiều từ M đến N, cảm ứng từ B do I gây ra trong khung dây chứa cạnh PQ có chiều từ sau ra trước, do R tăng nên B giảm dẫn đến từ thông qua mạch thay đổi, trong khung thứ hai có dòng điện cảm ứng sinh ra cảm ứng từ B' cùng chiều</em> <strong>B.</strong> <em>Dòng điện cảm ứng có chiều từ P đến Q nên lực từ tác dụng lên hai đoạn dây hút nhau.</em>","distractorNotes":{"B":"Xác định sai chiều dòng cảm ứng nên suy ngược kết luận lực giữa hai dòng điện.","C":"Cho rằng lực phụ thuộc vị trí trên đoạn dây: hai dòng điện song song chỉ hút hoặc đẩy nhau.","D":"Quên dòng điện cảm ứng ở mạch thứ hai đặt trong từ trường của $I$ nên chịu lực từ."},"difficultySource":null},"ex":[]},{"id":542,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["đẩy nhau.","hút nhau.","hút hay đẩy phụ thuộc tốc độ.","không tương tác."],"question":"Khi cho khung dây kín chuyển động ra xa dòng điện có cường độ <em>I</em> chạy trong dây dẫn thẳng dài vô hạn thì chúng sẽ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig47.png\" alt=\"Hình minh họa\">","difficulty":"kho","explanation":"<em>Khi cho khung dây kín chuyển động ra xa thì B giảm dẫn đến từ thông qua mạch giảm, trong khung có dòng điện cảm ứng sinh ra cảm ứng từ B' cùng chiều</em> <strong>B.</strong> <em>Dòng điện cảm ứng có chiều cùng chiều kim đồng hồ nên lực từ tác dụng lên chúng hút nhau.</em>","distractorNotes":{"B":"Xác định sai chiều dòng cảm ứng nên suy ngược kết luận hút hay đẩy.","C":"Lẫn độ lớn với chiều: tốc độ chỉ ảnh hưởng độ lớn $e$, không quyết định hút hay đẩy.","D":"Quên từ thông giảm thì vẫn có dòng cảm ứng, nên khung và dây vẫn tương tác."},"difficultySource":null},"ex":[]},{"id":543,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["có chiều <em>ABCD.</em>","có chiều <em>ADCB.</em>","cùng chiều với <em>I.</em>","bằng không."],"question":"Một khung dây hình chữ nhật chuyển động song song với dòng điện thẳng dài vô hạn. Dòng điện cảm ứng trong khung <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig48.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Một khung dây hình chữ nhật chuyển động song song với dòng điện thẳng dài vô hạn thì từ thông qua khung dây không đổi nên dòng điện cảm ứng trong khung bằng không.</em> <strong>C. Mức độ VẬN DỤNG</strong>","distractorNotes":{"B":"Bỏ qua việc từ thông không đổi nên không có suất điện động cảm ứng, rồi tự gán chiều dòng điện.","C":"Gán chiều dòng cảm ứng theo chiều $I$ mà không xét biến thiên từ thông qua khung.","D":"Phát biểu này đúng: khung chuyển động song song dòng điện thì từ thông không đổi nên không có dòng cảm ứng."},"difficultySource":null},"ex":[]},{"id":573,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["$0 V.$","$0,0025\\sqrt{3} V.$","$0,0025 V.$","$0,005 V.$"],"question":"Vòng dây kim loại diện tích 50 cm$^{2}$ hợp với véc tơ cảm ứng từ một góc 30$^\\circ$, cho biết cường độ của cảm ứng từ biến thiên theo thời gian như đồ thị, suất điện động cảm ứng trung bình sinh ra có giá trị <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig49.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Ta có</em> $e_{cu} = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{BS\\cos 60^\\circ}{\\Delta t} = -\\frac{\\Delta B.S\\cos 60^\\circ}{\\Delta t} = -\\frac{(0,2 - 0,1).50.10^{-4}.0,5}{0,2 - 0,1} = -0,0025 V.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig50.png\" alt=\"Hình minh họa\">","distractorNotes":{"A":"Cho rằng từ thông không đổi: quên rằng $B$ biến thiên nên từ thông vẫn thay đổi.","B":"Nhầm góc: dùng $\\cos30^\\circ=\\frac{\\sqrt3}{2}$ thay vì góc giữa pháp tuyến và $\\vec B$ là $60^\\circ$.","D":"Bỏ qua hệ số $\\cos$ của góc: lấy $\\Delta B\\cdot S$ nên kết quả gấp đôi."},"difficultySource":null},"ex":[]},{"id":580,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["từ 0 đến 0,1 s là 3 V.","từ 0,1 s đến 0,2 s là 6 V.","từ 0,2 s đến 0,3 s là 9 V.","từ 0 s đến 0,3 s là 4 V."],"question":"Từ thông qua một khung dây biến thiên theo thời gian biểu diễn như hình vẽ. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig51.png\" alt=\"Hình minh họa\"> Suất điện động cảm ứng trung bình trong khung dây trong các thời điểm tương ứng trong khoảng thời gian","difficulty":"de","explanation":"<em>Từ 0 đến 0,3s ta có</em> $|e_{c3}| = \\left|-\\frac{\\Delta\\phi}{\\Delta t}\\right| = \\frac{|\\phi_3 - \\phi_1|}{\\Delta t_3} = 4 V.$","distractorNotes":{"A":"Đọc sai độ biến thiên từ thông trên đồ thị đoạn 0–0,1 s, chia nhầm cho $\\Delta t$.","B":"Đọc sai $\\Delta\\Phi$ ở đoạn 0,1–0,2 s: lấy giá trị từ thông thay vì độ biến thiên.","D":"Phát biểu này đúng: $\\Delta\\Phi/\\Delta t$ trên cả đoạn 0–0,3 s cho 4 V."},"difficultySource":null},"ex":[]},{"id":587,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Cho một nam châm đưa lại gần vòng dây như hình. Xác định chiều dòng điện cảm ứng trong vòng dây và chiều dịch chuyển của vòng dây. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig52.png\" alt=\"Hình minh họa\">","difficulty":"kho","statements":[{"text":"Từ trường ban đầu $\\vec{B}$ do nam châm gây ra có chiều từ phải sang trái.","answer":false},{"text":"Đưa nam châm lại gần nên từ thông qua khung dây tăng nên $\\overrightarrow{B_c}$ ngược chiều $\\vec{B}$ nên $\\overrightarrow{B_c}$ có chiều từ phải sang trái và đi vào mặt vòng dây nên mặt vòng dây này là mặt Nam.","answer":true},{"text":"Chiều dòng điện $I_c$ ngược chiều kim đồng hồ.","answer":false},{"text":"Mặt đối diện của vòng dây với nam châm là mặt Bắc và do cực Bắc của nam châm lại gần mặt Bắc của vòng dây nên vòng dây bị đẩy ra xa.","answer":true}],"explanation":"<img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig53.png\" alt=\"Hình minh họa\"> <strong>a)</strong> <em>Từ trường ban đầu</em> $\\vec{B}$ <em>do nam châm gây ra có chiều từ trái sang phải (vào S ra N)</em> <strong>b)</strong> <em>Đưa nam châm lại gần nên từ thông qua khung dây tăng nên</em> $\\vec{B}_C$ <em>ngược chiều</em> $\\vec{B} \\Rightarrow \\vec{B}_C$ <em>có chiều từ phải sang trái và đi vào mặt vòng dây nên mặt vòng dây này là mặt Nam.</em> <strong>c)</strong> <em>Chiều dòng điện I</em>$_{C}$ <em>cùng chiều kim đồng hồ.</em> <strong>d)</strong> <em>Mặt đối diện của vòng dây với nam châm là mặt Bắc và do cực Bắc của nam châm lại gần mặt Bắc của vòng dây nên vòng dây bị đẩy ra xa.</em>","difficultySource":null},"ex":[]},{"id":590,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một cuộn đây đồng gồm nhiều vòng đặt gần một nam châm thẳng. Cuộn đây được di chuyển theo hướng mũi tên thể hiện trong sơ đồ. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig54.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Dòng điện cảm ứng trong cuộn dây chạy từ <em>B</em> đến <em>A.</em>","answer":false},{"text":"Nếu đổi cực nam châm thì trong cuộn dây sẽ không có dòng điện cảm ứng.","answer":false},{"text":"Khi di chuyển cuộn dây nhanh hơn thì dòng điện trong cuộn dây sẽ tăng lên.","answer":true},{"text":"Nếu cho cuộn dây và nam châm di chuyển cùng chiều với tốc độ không đổi thì dòng điện cảm ứng trong cuộn dây là dòng điện không đổi.","answer":false}],"explanation":"<strong>a)</strong> <em>Di chuyển cuộn dây lại gần nam châm thì từ thông qua cuộn dây tăng nên dòng điện cảm ứng trong cuộn dây có chiều sao cho từ trường do nó sinh ra ngược chiều từ trường của nam châm. Do</em> $\\vec{B}$ <em>của nam châm hướng sang trái nên</em> $\\vec{B}_C$ <em>do dòng điện cảm ứng trong cuộn dây sinh ra hướng sang phải Mặt B của cuộn dây là mặt Bắc và mặt A của cuộn dây là mặt Nam Dòng điện cảm ứng cùng chiều kim đồng hồ nhìn từ mặt A nên chạy từ A đến B.</em> <strong>b)</strong> <em>Khi đổi cực nam châm và cuộn dây di chuyển lại gần nam châm thì từ thông qua cuộn dây vẫn biến thiên và sinh ra dòng điện cảm ứng.</em> <strong>c)</strong> <em>Khi di chuyển cuộn dây nhanh lên thì tốc độ biến thiên từ thông qua cuộn dây sẽ tăng lên dòng điện trong cuộn dây sẽ tăng lên.</em> <em>d) Lúc này không có sự biến thiên từ thông qua cuộn dây nên không có dòng điện cảm ứng.</em>","difficultySource":null},"ex":[]},{"id":592,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Đồ thị sau đây cho thấy từ thông toàn phần qua một cuộn dây thay đổi theo thời gian (t) như đồ thị sau. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig56.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 0 đến 100 ms là 2 V.","answer":true},{"text":"Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 100 ms đến 300 ms là 0,5 V.","answer":false},{"text":"Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 300 ms đến 500 ms bằng không.","answer":true},{"text":"Độ lớn suất điện động sinh ra trong cuộn dây là lớn nhất trong khoảng thời gian từ 0 đến 100 ms.","answer":true}],"explanation":"<strong>a)</strong> <em>Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 0 đến 100 ms là</em> $e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{\\Phi_2 - \\Phi_1}{t_2 - t_1} = -\\frac{0,2 - 0}{0,1} = -2\\,\\mathrm{V}.$ <strong>b)</strong> <em>Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 100 ms đến 300 ms là</em> $e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{\\Phi_3 - \\Phi_2}{t_3 - t_2} = -\\frac{0,15 - 0,2}{0,2} = 0,25\\,\\mathrm{V}.$ <strong>c)</strong> <em>Suất điện động cảm ứng trung bình xuất hiện ở cuộn đây trong khoảng thời gian từ 300 ms đến 500 ms là</em> $e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = 0.$ <strong>d)</strong> <em>Gal Vì từ 0 đến 100ms đồ thị dốc nhất nên tốc độ biến thiên từ thông lớn nhất $\\to$ độ lớn suất điện động sinh ra là lớn nhất</em>","difficultySource":null},"ex":[]},{"id":593,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Đồ thị sau đây biểu diễn sự biến thiên của từ thông toàn phần theo thời gian trong một cuộn dây phẳng. Biết từ thông qua cuộn dây biến đổi chỉ do từ trường qua cuộn dây thay đổi và từ trường này có đường cảm ứng từ vuông góc mặt phẳng cuộn dây. Nếu diện tích mặt cắt ngang của cuộn dây là $1,6.10^{-2}\\,\\mathrm{m}^2$ và cuộn dây có 500 vòng dây. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig57.png\" alt=\"Hình minh họa\">","difficulty":"kho","statements":[{"text":"Suất điện động cảm ứng trong cuộn dây có độ lớn cực đại khi tốc độ biến thiên của từ thông qua cuộn dây đạt giá trị cực tiểu.","answer":false},{"text":"Tốc độ biến thiên của từ thông đạt cực đại tại các thời điểm đồ thị có độ dốc lớn nhất.","answer":true},{"text":"Tại các thời điểm 0 ms, 20 ms, 40 ms, 80 ms hoặc 100 ms suất điện động có giá trị cực đại, lúc này từ thông bằng 0.","answer":true},{"text":"Độ lớn từ trường cực đại là 0,2 T.","answer":false}],"explanation":"<strong>a)</strong> <em>Từ công thức</em> $e = \\left|-N\\frac{\\Delta\\Phi}{\\Delta t}\\right|,$ <em>ta thấy suất điện động cảm ứng trong cuộn dây có độ lớn cực đại khi tốc độ biến thiên của từ thông qua cuộn dây đạt giá trị cực đại.</em> <strong>b)</strong> <em>Dựa vào đồ thị, tốc độ biến thiên của từ thông đạt cực đại tại các thời điểm đồ thị có độ dốc lớn nhất.</em> <strong>c)</strong> <em>Tại các thời điểm 0 ms, 20 ms, 40 ms, 80 ms hoặc 100 ms suất điện động có giá trị cực đại, lúc này từ thông bằng 0.</em> <strong>d)</strong> <em>Độ lớn từ trường cực đại, từ</em> $\\Phi = NBS \\Rightarrow B_{max} = \\frac{\\Phi_{max}}{NS} = \\frac{2}{500.1,6.10^{-2}} = 0,25\\,\\mathrm{T}.$","difficultySource":null},"ex":[]},{"id":596,"nq":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Đặt khung dây dẫn <em>ABCD</em> cạnh một dây dẫn thẳng có dòng điện chạy qua như hình vẽ. Thanh <em>AB</em> có thể trượt trên hai thanh <em>DE</em> và <em>CF</em>. Điện trở <em>R</em> không đổi và bỏ qua điện trở của các thanh <em>AB</em> song song với dòng điện thẳng và chuyển động thẳng đều với vận tốc vuông góc với <em>AB.</em> <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig58.png\" alt=\"Hình minh họa\">","difficulty":"kho","statements":[{"text":"Vectơ cảm ứng từ do dòng <em>I</em> sinh ra có chiều hướng từ trong ra ngoài.","answer":true},{"text":"Dòng điện cảm ứng có chiều từ <em>A</em> đến <em>B.</em>","answer":false},{"text":"Vectơ cảm ứng từ tại các vị trí khác nhau là như nhau.","answer":false},{"text":"Khi từ trường thay đổi thì dòng điện thay đổi.","answer":true}],"explanation":"<strong>a)</strong> <em>Từ trường</em> $\\vec{B}$ <em>do dòng I sinh ra có chiều hướng từ trong ra ngoài (quy tắc nắm bàn tay phải cho dòng điện thẳng dài).</em> <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig59.png\" alt=\"Hình minh họa\"> <strong>b)</strong> <em>Vận dụng quy tắc bàn tay phải cho đoạn dây AB thì dòng điện cảm ứng có chiều từ B đến A.</em> <strong>c)</strong> <em>Từ trường</em> $\\vec{B}$ <em>tại các vị trí khác nhau là khác nhau, càng gần I thì B càng lớn.</em> <strong>d)</strong> <em>Dòng điện trong mạch được tính theo công thức</em> $\\begin{cases} i = \\frac{e_c}{R} = \\frac{Bvl}{R} B = 2.10^{-7}.\\frac{I}{r} \\end{cases}$ <em>Vì B thay đổi nên i thay đổi cả chiều lẫn độ lớn.</em>","difficultySource":null},"ex":[]},{"id":600,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Trong tráp treo trên cao, một máy dò nhỏ gắn với máy phát hiện sóng tia âm cực được đặt gần cáp để theo dõi dòng điện xoay chiều đi qua cáp. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig61.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Suất điện động cảm ứng trong máy dò phụ thuộc vào diện tích đặt vuông góc với cảm ứng từ. Với hình a mặt phẳng cuộn dây song song với dây dẫn sẽ cho từ thông qua cuộn dây là lớn nhất.","answer":true},{"text":"Suất điện động cảm ứng trên máy dò không phụ thuộc vào tốc độ thay đổi của từ thông.","answer":false},{"text":"Khi đặt mặt phẳng cuộn dây máy dò theo hướng vuông góc với sợi dây (hình b) thì không có sự biến thiên từ thông qua cuộn dây nên không có dòng điện cảm ứng trong máy dò.","answer":true},{"text":"Từ trường do dòng điện xoay chiều gây ra sẽ thay đổi, do đó sẽ tạo ra một suất điện động trong máy dò.","answer":true}],"explanation":"<strong>b)</strong> <em>Suất điện động cảm ứng trên máy dò phụ thuộc vào tốc độ thay đổi của từ thông. Khi đặt như hình b thì từ thông qua cuộn dây máy dò bằng 0</em>","difficultySource":null},"ex":[]},{"id":614,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"6","question":"Một cuộn dây hình chữ nhật đang quay với tốc độ góc không đổi với trục quay vuông góc với từ trường đều 0,15 T. Tại thời điểm như hình vẽ, góc giữa mặt phẳng khung dây và từ trường là 30$^\\circ$. Cuộn dây có 50 vòng và có diện tích mặt cắt ngang là $4.10^{-4}\\,\\mathrm{m}^2.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig63.png\" alt=\"Hình minh họa\"> Cuộn dây chuyển động quay quanh trục từ vị trí như hình đến vị trí mà từ thông qua cuộn dây bằng 0 trong khoảng thời gian 0,25 s. Tính giá trị trung bình của suất điện động cảm ứng trong cuộn dây theo đơn vị mV?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">$$\\Phi_N = NBS.\\sin\\theta = 50.0,15.4.10^{-4}.\\sin 30^\\circ = 1,5.10^{-5}\\,\\mathrm{Wb}.$$ $$e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{NBS(\\cos\\alpha_2 - \\cos\\alpha_1)}{\\Delta t} = -\\frac{50.0,15.4.10^{-4}.(-\\cos 60^\\circ)}{0,25} = e_c = 6.10^{-3}\\,\\mathrm{V} = 6\\,\\mathrm{mV}.$$</p>","difficultySource":null},"ex":[]},{"id":615,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"0,2","question":"Thanh dẫn điện <em>CD</em> có chiều dài 20 cm, điện trở 0,5 Ω chuyển động tịnh tiến trong từ trường đều có độ lớn cảm ứng từ 0,2 T với vận tốc không đổi 10 m/s, vuông góc với các đường sức từ. Khi chuyển động thanh <em>CD</em> hướng không đổi, luôn tiếp xúc với hai đầu một mạch điện có điện trở 1,5 Ω như hình vẽ. Cường độ dòng điện cảm ứng xuất hiện trong thanh là bao nhiêu ampe? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig64.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Ta có</em> $|e_c| = Blv\\sin\\theta = 0,2.0,2.10 = 0,4\\,\\mathrm{V}.$ <em>Cường độ dòng điện cảm ứng xuất hiện trong thanh:</em> $I = \\frac{|e_c|}{R + r} = 0,2\\,\\mathrm{A}.$","difficultySource":null},"ex":[]},{"id":628,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây tịnh tiến với vận tốc $\\vec{v}$ trong từ trường đều? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig65.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Hình 3: từ thông qua khung dây không đổi nên không có dòng điện cảm ứng trong mạch</em>","distractorNotes":{"B":"Xác định ngược chiều dòng cảm ứng do áp dụng sai quy tắc bàn tay phải hoặc định luật Lenz.","C":"Bỏ sót bước xét từ thông: tịnh tiến trong từ trường đều thì từ thông không đổi, không có dòng cảm ứng.","D":"Đổi chiều dòng cảm ứng khi xác định chiều từ trường hoặc chiều chuyển động của vòng dây."},"difficultySource":null},"ex":[{"exam":18,"idx":10,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây tịnh tiến với vận tốc $\\vec{v}$ trong từ trường đều? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig65.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Hình 3: từ thông qua khung dây không đổi nên không có dòng điện cảm ứng trong mạch</em>","distractorNotes":{"B":"Xác định ngược chiều dòng cảm ứng do áp dụng sai quy tắc bàn tay phải hoặc định luật Lenz.","C":"Bỏ sót bước xét từ thông: tịnh tiến trong từ trường đều thì từ thông không đổi, không có dòng cảm ứng.","D":"Đổi chiều dòng cảm ứng khi xác định chiều từ trường hoặc chiều chuyển động của vòng dây."}}}]},{"id":629,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":0,"options":["vuông góc với mặt phẳng hình vẽ và hướng ra phía sau mặt phẳng hình vẽ.","vuông góc với mặt phẳng hình vẽ và hướng ra phía trước mặt phẳng hình vẽ.","nằm trong mặt phẳng hình vẽ và vuông góc với hai thanh ray.","nằm trong mặt phẳng hình vẽ và song song với hai thanh ray."],"question":"Trong mặt phẳng hình vẽ, thanh kim loại MN chuyển động trong từ trường đều thì dòng điện cảm ứng trong mạch có chiều như trên hình. Nếu vậy, các đường sức từ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig83.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Theo quy tắc bàn tay phải</em> <em>+ Từ cổ tay đến ngón tay chỉ chiều dòng điện từ M đến N</em> <em>+ Ngón tay cái chỉ chiều chuyển động của thanh MN</em> <em>$\\to$</em> $\\vec{B}$ <em>xuyên vào lòng bàn tay $\\to$</em> $\\vec{B}$ <em>có phương vuông góc với mặt phẳng hình vẽ và hướng ra phía sau mặt phẳng hình vẽ.</em>","distractorNotes":{"B":"Đảo hướng của $\\vec{B}$: nhầm hướng ra phía sau với hướng ra phía trước khi đặt bàn tay phải.","C":"Đặt $\\vec{B}$ nằm trong mặt phẳng mạch nên lực từ không tạo dòng dọc thanh MN.","D":"Cho $\\vec{B}$ song song với ray, tức song song với $\\vec{v}$, nên không có suất điện động cảm ứng."},"difficultySource":null},"ex":[{"exam":18,"idx":11,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Suất điện động do thanh dẫn chuyển động","answer":0,"options":["vuông góc với mặt phẳng hình vẽ và hướng ra phía sau mặt phẳng hình vẽ.","vuông góc với mặt phẳng hình vẽ và hướng ra phía trước mặt phẳng hình vẽ.","nằm trong mặt phẳng hình vẽ và vuông góc với hai thanh ray.","nằm trong mặt phẳng hình vẽ và song song với hai thanh ray."],"question":"Trong mặt phẳng hình vẽ, thanh kim loại MN chuyển động trong từ trường đều thì dòng điện cảm ứng trong mạch có chiều như trên hình. Nếu vậy, các đường sức từ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig83.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Theo quy tắc bàn tay phải</em> <em>+ Từ cổ tay đến ngón tay chỉ chiều dòng điện từ M đến N</em> <em>+ Ngón tay cái chỉ chiều chuyển động của thanh MN</em> <em>$\\to$</em> $\\vec{B}$ <em>xuyên vào lòng bàn tay $\\to$</em> $\\vec{B}$ <em>có phương vuông góc với mặt phẳng hình vẽ và hướng ra phía sau mặt phẳng hình vẽ.</em>","distractorNotes":{"B":"Đảo hướng của $\\vec{B}$: nhầm hướng ra phía sau với hướng ra phía trước khi đặt bàn tay phải.","C":"Đặt $\\vec{B}$ nằm trong mặt phẳng mạch nên lực từ không tạo dòng dọc thanh MN.","D":"Cho $\\vec{B}$ song song với ray, tức song song với $\\vec{v}$, nên không có suất điện động cảm ứng."}}}]},{"id":630,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây dịch chuyển lại gần hay ra xa nam châm? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig66.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Từ thông tăng nên</em> $\\vec{B'} \\uparrow\\downarrow \\vec{B}$ <em>áp dụng quy tắc bàn tay phải ta có chiều dòng điện như hình vẽ</em> <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig29.png\" alt=\"Hình minh họa\">","difficultySource":null},"ex":[{"exam":18,"idx":12,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":0,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây dịch chuyển lại gần hay ra xa nam châm? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig66.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Từ thông tăng nên</em> $\\vec{B'} \\uparrow\\downarrow \\vec{B}$ <em>áp dụng quy tắc bàn tay phải ta có chiều dòng điện như hình vẽ</em> <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig29.png\" alt=\"Hình minh họa\">"}}]},{"id":632,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["$I,\\ IV.$","$III,\\ IV.$","$II,\\ III.$","$I,\\ II.$"],"question":"Một khung dây $ABCD$ được đặt đồng phẳng với một dòng điện thẳng dài vô hạn, cạnh $AC$ song song với dòng điện. Tịnh tiến khung dây theo các cách sau $I.$ Đi lên, khoảng cách giữa tâm khung dây và dòng diện thẳng không đổi. $II.$ Đi xuống, khoảng cách giữa tâm khung dây và dòng diện thẳng không đổi. $III.$ Đi ra xa dòng điện. $IV.$ Đi về gần dòng điện. Trường hợp nào xuất hiện dòng điện cảm ứng trong khung $ABCD?$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig67.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Một khung dây ABCD được đặt đồng phẳng với một dòng điện thẳng dài vô hạn, cạnh AC song song với dòng điện ta tịnh tiến khung dây ra xa hoặc lại gần sẽ làm biến thiên từ thông qua khung, dẫn đến xuất hiện dòng điện cảm ứng trong khung.</em>","distractorNotes":{"A":"Cho rằng đi lên làm từ thông đổi, nhưng khoảng cách tới dòng điện không đổi nên $B$ không đổi.","C":"Cho rằng đi xuống làm từ thông biến thiên, dù khoảng cách tới dây dẫn vẫn giữ nguyên.","D":"Tịnh tiến song song với dòng điện, từ thông không đổi; nhầm với trường hợp thay đổi khoảng cách."},"difficultySource":null},"ex":[{"exam":18,"idx":14,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":1,"options":["$I,\\ IV.$","$III,\\ IV.$","$II,\\ III.$","$I,\\ II.$"],"question":"Một khung dây $ABCD$ được đặt đồng phẳng với một dòng điện thẳng dài vô hạn, cạnh $AC$ song song với dòng điện. Tịnh tiến khung dây theo các cách sau $I.$ Đi lên, khoảng cách giữa tâm khung dây và dòng diện thẳng không đổi. $II.$ Đi xuống, khoảng cách giữa tâm khung dây và dòng diện thẳng không đổi. $III.$ Đi ra xa dòng điện. $IV.$ Đi về gần dòng điện. Trường hợp nào xuất hiện dòng điện cảm ứng trong khung $ABCD?$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig67.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Một khung dây ABCD được đặt đồng phẳng với một dòng điện thẳng dài vô hạn, cạnh AC song song với dòng điện ta tịnh tiến khung dây ra xa hoặc lại gần sẽ làm biến thiên từ thông qua khung, dẫn đến xuất hiện dòng điện cảm ứng trong khung.</em>","distractorNotes":{"A":"Cho rằng đi lên làm từ thông đổi, nhưng khoảng cách tới dòng điện không đổi nên $B$ không đổi.","C":"Cho rằng đi xuống làm từ thông biến thiên, dù khoảng cách tới dây dẫn vẫn giữ nguyên.","D":"Tịnh tiến song song với dòng điện, từ thông không đổi; nhầm với trường hợp thay đổi khoảng cách."}}}]},{"id":635,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":3,"options":["$10^{-4}\\ V.$","$1,2.10^{-4}\\ V.$","$1,3.10^{-4}\\ V.$","$1,5.10^{-4}\\ V.$"],"question":"Một khung dây cứng phẳng diện tích $25\\ cm^2$ gồm $10$ vòng dây, đặt trong từ trường đều, mặt phẳng khung vuông góc với các đường cảm ứng từ. Cảm ứng từ biến thiên như hình vẽ. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig68.png\" alt=\"Hình minh họa\"> Suất điện động cảm ứng xuất hiện trong khung kể từ $t = 0$ đến $t = 0,4\\ s$ là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">$$|e_c| = \\left|-\\frac{\\Delta\\phi}{\\Delta t}\\right| = NS\\cos\\alpha\\left|\\frac{B_2 - B_1}{\\Delta t}\\right| = 1,5.10^{-4}\\ V.$$</p>","distractorNotes":{"A":"Đọc sai giá trị $B$ trên đồ thị nên độ biến thiên $\\Delta B$ bị lệch.","B":"Lấy sai mốc thời gian hoặc mốc $B$ khi tính tỉ số $\\Delta B/\\Delta t$ từ đồ thị.","C":"Tính độ dốc của một đoạn đồ thị thay vì $\\Delta B$ trên toàn khoảng 0 đến 0,4 s."},"difficultySource":null},"ex":[{"exam":18,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":3,"options":["$10^{-4}\\ V.$","$1,2.10^{-4}\\ V.$","$1,3.10^{-4}\\ V.$","$1,5.10^{-4}\\ V.$"],"question":"Một khung dây cứng phẳng diện tích $25\\ cm^2$ gồm $10$ vòng dây, đặt trong từ trường đều, mặt phẳng khung vuông góc với các đường cảm ứng từ. Cảm ứng từ biến thiên như hình vẽ. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig68.png\" alt=\"Hình minh họa\"> Suất điện động cảm ứng xuất hiện trong khung kể từ $t = 0$ đến $t = 0,4\\ s$ là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">$$|e_c| = \\left|-\\frac{\\Delta\\phi}{\\Delta t}\\right| = NS\\cos\\alpha\\left|\\frac{B_2 - B_1}{\\Delta t}\\right| = 1,5.10^{-4}\\ V.$$</p>","distractorNotes":{"A":"Đọc sai giá trị $B$ trên đồ thị nên độ biến thiên $\\Delta B$ bị lệch.","B":"Lấy sai mốc thời gian hoặc mốc $B$ khi tính tỉ số $\\Delta B/\\Delta t$ từ đồ thị.","C":"Tính độ dốc của một đoạn đồ thị thay vì $\\Delta B$ trên toàn khoảng 0 đến 0,4 s."}}}]},{"id":637,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Hình dưới đây mô tả khi thanh nam châm dịch chuyền lại gần ống dây, trong ống dây có dòng điện cảm ứng. Nếu nhìn từ phía thanh nam châm vào đầu ống dây thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig85.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"dòng điện chạy theo chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và hút cực bắc của thanh nam châm.","answer":false},{"text":"dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và đẩy cực bắc của thanh nam châm.","answer":true},{"text":"dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực nam của ống dây và đẩy cực nam của thanh nam châm","answer":false},{"text":"dòng điện chạy theo chiều kim đồng hồ, đầu 1 là cực nam của ống dây và hút cực bắc của thanh nam châm.","answer":false}],"explanation":"<strong>a)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây phải có chiều sao cho đầu 1 của ống dây là cực bắc và nó phải đẩy cực bắc của thanh nam châm.</em> <strong>b)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây có chiều sao cho đầu 1 của ống dây là cực bắc và nó đẩy cực bắc của thanh nam châm.</em> <strong>c)</strong> <em>Dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và hút cực nam của thanh nam châm.</em> <strong>d)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây phải có chiều sao cho đầu 1 của ống dây là cực bắc.</em>","difficultySource":null},"ex":[{"exam":18,"idx":19,"el":{"form":"ly_thuyet","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Hình dưới đây mô tả khi thanh nam châm dịch chuyền lại gần ống dây, trong ống dây có dòng điện cảm ứng. Nếu nhìn từ phía thanh nam châm vào đầu ống dây thì <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig85.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"dòng điện chạy theo chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và hút cực bắc của thanh nam châm.","answer":false},{"text":"dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và đẩy cực bắc của thanh nam châm.","answer":true},{"text":"dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực nam của ống dây và đẩy cực nam của thanh nam châm","answer":false},{"text":"dòng điện chạy theo chiều kim đồng hồ, đầu 1 là cực nam của ống dây và hút cực bắc của thanh nam châm.","answer":false}],"explanation":"<strong>a)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây phải có chiều sao cho đầu 1 của ống dây là cực bắc và nó phải đẩy cực bắc của thanh nam châm.</em> <strong>b)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây có chiều sao cho đầu 1 của ống dây là cực bắc và nó đẩy cực bắc của thanh nam châm.</em> <strong>c)</strong> <em>Dòng điện chạy ngược chiều kim đồng hồ, đầu 1 là cực bắc của ống dây và hút cực nam của thanh nam châm.</em> <strong>d)</strong> <em>Khi đưa cực bắc của thanh nam châm lại gần đầu 1 của ống dây, dòng điện cảm ứng trong ống dây phải có chiều sao cho đầu 1 của ống dây là cực bắc.</em>"}}]},{"id":638,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Bố trí thí nghiệm như hình, một điện kế có vạch số 0 ở giữa được mắc vào hai đầu một ống đây tạo thành mạch kín. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig69.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Trong khoảng thời gian nam châm địch chuyển lại gần ống dây sẽ gây ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Đưa cực Bắc của nam châm ra xa ống dây thì kim điện kế bị lệch về phía dương.","answer":false},{"text":"Cho nam châm di chuyển về phía cuộn dây với tốc độ lớn thì kim điện kế lệch về phía dương rất nhanh.","answer":true},{"text":"Nếu giữ nam châm cố định và quay cuộn dây xung quanh trục của nó, kim điện kế sẽ không bị lệch.","answer":true}],"explanation":"<strong>a)</strong> <em>Khi nam châm dịch chuyển lại gần ống dây làm từ thông qua ống dây biến thiên nên gây ra hiện tượng cảm ứng điện từ.</em> <strong>b)</strong> <em>Khi nam châm ra xa ống dây, từ thông qua ống dây giảm suất điện động cảm ứng giảm cường độ dòng điện giảm nên làm kim điện kế lệch về phía âm.</em> <strong>c)</strong> <em>Khi nam châm di chuyển về phía cuộn dây với tốc độ lớn thì tốc độ biến</em> <strong>thiên từ thông lớn suất điện động cảm ứng tăng cường độ dòng điện tăng</strong> <em>làm kim điện kế lệch về phía dương rất nhanh.</em> <strong>d)</strong> <em>Do số đường sức từ qua cuộn dây không đổi nên không có sự biến thiên từ thông nào qua cuộn dây Trong cuộn dây không có dòng điện cảm ứng.</em>","difficultySource":null},"ex":[{"exam":18,"idx":20,"el":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Bố trí thí nghiệm như hình, một điện kế có vạch số 0 ở giữa được mắc vào hai đầu một ống đây tạo thành mạch kín. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig69.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Trong khoảng thời gian nam châm địch chuyển lại gần ống dây sẽ gây ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Đưa cực Bắc của nam châm ra xa ống dây thì kim điện kế bị lệch về phía dương.","answer":false},{"text":"Cho nam châm di chuyển về phía cuộn dây với tốc độ lớn thì kim điện kế lệch về phía dương rất nhanh.","answer":true},{"text":"Nếu giữ nam châm cố định và quay cuộn dây xung quanh trục của nó, kim điện kế sẽ không bị lệch.","answer":true}],"explanation":"<strong>a)</strong> <em>Khi nam châm dịch chuyển lại gần ống dây làm từ thông qua ống dây biến thiên nên gây ra hiện tượng cảm ứng điện từ.</em> <strong>b)</strong> <em>Khi nam châm ra xa ống dây, từ thông qua ống dây giảm suất điện động cảm ứng giảm cường độ dòng điện giảm nên làm kim điện kế lệch về phía âm.</em> <strong>c)</strong> <em>Khi nam châm di chuyển về phía cuộn dây với tốc độ lớn thì tốc độ biến</em> <strong>thiên từ thông lớn suất điện động cảm ứng tăng cường độ dòng điện tăng</strong> <em>làm kim điện kế lệch về phía dương rất nhanh.</em> <strong>d)</strong> <em>Do số đường sức từ qua cuộn dây không đổi nên không có sự biến thiên từ thông nào qua cuộn dây Trong cuộn dây không có dòng điện cảm ứng.</em>"}},{"exam":259,"idx":19,"el":{"form":"ly_thuyet","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Bố trí thí nghiệm như hình, một điện kế có vạch số 0 ở giữa được mắc vào hai đầu một ống đây tạo thành mạch kín. <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig69.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","statements":[{"text":"Trong khoảng thời gian nam châm địch chuyển lại gần ống dây sẽ gây ra hiện tượng cảm ứng điện từ.","answer":true},{"text":"Đưa cực Bắc của nam châm ra xa ống dây thì kim điện kế bị lệch về phía dương.","answer":false},{"text":"Cho nam châm di chuyển về phía cuộn dây với tốc độ lớn thì kim điện kế lệch về phía dương rất nhanh.","answer":true},{"text":"Nếu giữ nam châm cố định và quay cuộn dây xung quanh trục của nó, kim điện kế sẽ không bị lệch.","answer":true}],"explanation":"<strong>a)</strong> <em>Khi nam châm dịch chuyển lại gần ống dây làm từ thông qua ống dây biến thiên nên gây ra hiện tượng cảm ứng điện từ.</em> <strong>b)</strong> <em>Khi nam châm ra xa ống dây, từ thông qua ống dây giảm suất điện động cảm ứng giảm cường độ dòng điện giảm nên làm kim điện kế lệch về phía âm.</em> <strong>c)</strong> <em>Khi nam châm di chuyển về phía cuộn dây với tốc độ lớn thì tốc độ biến</em> <strong>thiên từ thông lớn suất điện động cảm ứng tăng cường độ dòng điện tăng</strong> <em>làm kim điện kế lệch về phía dương rất nhanh.</em> <strong>d)</strong> <em>Do số đường sức từ qua cuộn dây không đổi nên không có sự biến thiên từ thông nào qua cuộn dây Trong cuộn dây không có dòng điện cảm ứng.</em>"}}]},{"id":639,"nq":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Cho mạch điện như hình vẽ dưới đây Suất điện động nguồn điện $E = 1,5\\ V$ và điện trở trong $r = 0,2\\ \\Omega.$ Thanh MN dài 1 m và có điện trở $R_{MN} = 2,8\\ \\Omega.$ Cảm ứng từ có độ lớn $B = 0,1\\ T.$ Bỏ qua điện trở của ampe kế $A.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig70.png\" alt=\"Hình minh họa\">","difficulty":"kho","statements":[{"text":"Số chỉ của ampe kế khi thanh MN đứng yên là $0,5\\ A.$","answer":true},{"text":"Khi thanh MN chuyển động, trong thanh xuất hiện suất điện động cảm ứng $e_c.$","answer":true},{"text":"Khi thanh MN chuyển động đều về bên phải với vận tốc $v = 5\\ m/s$ thì dòng điện cảm ứng sinh ra ngược chiều với dòng điện I và có độ lớn là $\\frac{2}{3}\\ A.$","answer":false},{"text":"Muốn cho ampe kế chỉ 0 thì phải dịch chuyển MN về phía bên trái với vận tốc bằng $5\\ m/s.$","answer":false}],"explanation":"<strong>a)</strong> <em>Khi MN đứng yên số chỉ ampe kế là</em> $I = \\frac{E}{R_{MN} + r} = \\frac{1,5}{2,8 + 0,2} = 0,5\\ A.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig70.png\" alt=\"Hình minh họa\"> <strong>c)</strong> <em>Khi MN chuyển động, trong thanh xuất hiện suất điện động cảm ứng</em> $e_c = Blv = 0,1.5.1 = 0,5\\ V$ <em>Cường độ dòng điện cảm ứng</em> $I_c = \\frac{e_c}{R_{MN} + r}$ <em>Dùng quy tắc bàn tay phải, xác định được I</em>$_{c}$ <em>cùng chiều I</em> $\\Rightarrow I_A = I + I_c = \\frac{E + e_c}{R_{MN} + r} = \\frac{1,5 + 0,5}{2,8 + 0,2} = \\frac{2}{3}\\ A.$ <strong>d)</strong> <em>Muốn I</em>$_{c}$ <em>ngược chiều thì thanh MN phải dịch chuyển về phía ngược lại (về phía trái).</em> <em>Để</em> $I_A = I - I_c = 0$ <em>thì</em> $e_c = E \\Leftrightarrow Bv'l = 1,5 \\Leftrightarrow v' = \\frac{1,5}{Bl} = \\frac{1,5}{0,1.1} = 15\\ m/s$","difficultySource":null},"ex":[{"exam":18,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Suất điện động do thanh dẫn chuyển động","question":"Cho mạch điện như hình vẽ dưới đây Suất điện động nguồn điện $E = 1,5\\ V$ và điện trở trong $r = 0,2\\ \\Omega.$ Thanh MN dài 1 m và có điện trở $R_{MN} = 2,8\\ \\Omega.$ Cảm ứng từ có độ lớn $B = 0,1\\ T.$ Bỏ qua điện trở của ampe kế $A.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig70.png\" alt=\"Hình minh họa\">","difficulty":"kho","statements":[{"text":"Số chỉ của ampe kế khi thanh MN đứng yên là $0,5\\ A.$","answer":true},{"text":"Khi thanh MN chuyển động, trong thanh xuất hiện suất điện động cảm ứng $e_c.$","answer":true},{"text":"Khi thanh MN chuyển động đều về bên phải với vận tốc $v = 5\\ m/s$ thì dòng điện cảm ứng sinh ra ngược chiều với dòng điện I và có độ lớn là $\\frac{2}{3}\\ A.$","answer":false},{"text":"Muốn cho ampe kế chỉ 0 thì phải dịch chuyển MN về phía bên trái với vận tốc bằng $5\\ m/s.$","answer":false}],"explanation":"<strong>a)</strong> <em>Khi MN đứng yên số chỉ ampe kế là</em> $I = \\frac{E}{R_{MN} + r} = \\frac{1,5}{2,8 + 0,2} = 0,5\\ A.$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig70.png\" alt=\"Hình minh họa\"> <strong>c)</strong> <em>Khi MN chuyển động, trong thanh xuất hiện suất điện động cảm ứng</em> $e_c = Blv = 0,1.5.1 = 0,5\\ V$ <em>Cường độ dòng điện cảm ứng</em> $I_c = \\frac{e_c}{R_{MN} + r}$ <em>Dùng quy tắc bàn tay phải, xác định được I</em>$_{c}$ <em>cùng chiều I</em> $\\Rightarrow I_A = I + I_c = \\frac{E + e_c}{R_{MN} + r} = \\frac{1,5 + 0,5}{2,8 + 0,2} = \\frac{2}{3}\\ A.$ <strong>d)</strong> <em>Muốn I</em>$_{c}$ <em>ngược chiều thì thanh MN phải dịch chuyển về phía ngược lại (về phía trái).</em> <em>Để</em> $I_A = I - I_c = 0$ <em>thì</em> $e_c = E \\Leftrightarrow Bv'l = 1,5 \\Leftrightarrow v' = \\frac{1,5}{Bl} = \\frac{1,5}{0,1.1} = 15\\ m/s$"}}]},{"id":643,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"64","question":"Một vòng dây dẫn phẳng có diện tích $S = 160\\ cm^2$ được đặt vuông góc với cảm ứng từ trong một từ trường đồng nhất nhưng có độ lớn tăng đều với tốc độ $0,02\\ T/s.$ Biết tổng điện trở của mạch là $5,0\\ \\Omega.$ Cường độ của dòng điện cảm ứng trong vòng dây là bao nhiêu $\\muA?$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig71.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Theo đề bài, diện tích vòng dây không đổi, từ thông biến thiên do cảm ứng từ biến thiên. Độ lớn của suất điện động cảm ứng là</em> $e_c = \\frac{\\Delta\\Phi}{\\Delta t} = S\\frac{\\Delta B}{\\Delta t} = 160.10^{-4}.0,02 = 3,2.10^{-4}\\ V.$ <em>Cường độ của dòng điện cảm ứng là</em> $i_C = \\frac{e_c}{R} = \\frac{3,2.10^{-4}}{5} = 6,4.10^{-5}\\ A = 64\\ \\muA.$","difficultySource":null},"ex":[{"exam":18,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"64","question":"Một vòng dây dẫn phẳng có diện tích $S = 160\\ cm^2$ được đặt vuông góc với cảm ứng từ trong một từ trường đồng nhất nhưng có độ lớn tăng đều với tốc độ $0,02\\ T/s.$ Biết tổng điện trở của mạch là $5,0\\ \\Omega.$ Cường độ của dòng điện cảm ứng trong vòng dây là bao nhiêu $\\muA?$ <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig71.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Theo đề bài, diện tích vòng dây không đổi, từ thông biến thiên do cảm ứng từ biến thiên. Độ lớn của suất điện động cảm ứng là</em> $e_c = \\frac{\\Delta\\Phi}{\\Delta t} = S\\frac{\\Delta B}{\\Delta t} = 160.10^{-4}.0,02 = 3,2.10^{-4}\\ V.$ <em>Cường độ của dòng điện cảm ứng là</em> $i_C = \\frac{e_c}{R} = \\frac{3,2.10^{-4}}{5} = 6,4.10^{-5}\\ A = 64\\ \\muA.$"}}]},{"id":645,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"3","question":"Từ thông qua khung dây biến đổi theo thời gian được diễn tả bằng đồ thị trên hình vẽ. Suất điện động cảm ứng trong khung trong khoảng thời gian từ 0 s đến 0,2 s là bao nhiêu Vold? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig73.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Từ t = 0s đến t = 0,2, từ thông giảm đều từ</em> $1,2\\ Wb$ <em>về</em> $0,6\\ Wb$ $\\Rightarrow e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{0,6 - 1,2}{0,2 - 0} = 3\\ V.$","difficultySource":null},"ex":[{"exam":18,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"3","question":"Từ thông qua khung dây biến đổi theo thời gian được diễn tả bằng đồ thị trên hình vẽ. Suất điện động cảm ứng trong khung trong khoảng thời gian từ 0 s đến 0,2 s là bao nhiêu Vold? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig73.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<em>Từ t = 0s đến t = 0,2, từ thông giảm đều từ</em> $1,2\\ Wb$ <em>về</em> $0,6\\ Wb$ $\\Rightarrow e_c = -\\frac{\\Delta\\Phi}{\\Delta t} = -\\frac{0,6 - 1,2}{0,2 - 0} = 3\\ V.$"}}]},{"id":653,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":3,"options":["hình 4.","hình 3.","hình 2.","hình 1."],"question":"<p>Hai kim nam châm nhỏ đặt trên Trái Đất xa các dòng điện và các nam châm khác; đường nối hai trọng tâm của chúng nằm theo hướng Nam – Bắc. Nếu từ trường Trái Đất mạnh hơn từ trường kim nam châm, khi cân bằng, hai kim nam châm đó sẽ có dạng như</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c08.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường Trái Đất mạnh hơn nên cả hai kim đều bị định hướng theo hướng Nam – Bắc của Trái Đất: cực Bắc của mỗi kim chỉ về phía Bắc, tức hai kim xếp thành S–N, S–N như hình 1. Cách xếp này đồng thời cho cực Bắc kim này hướng về cực Nam kim kia nên hai kim hút nhau, cân bằng bền.</p>","difficultySource":null},"ex":[{"exam":19,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":3,"options":["hình 4.","hình 3.","hình 2.","hình 1."],"question":"<p>Hai kim nam châm nhỏ đặt trên Trái Đất xa các dòng điện và các nam châm khác; đường nối hai trọng tâm của chúng nằm theo hướng Nam – Bắc. Nếu từ trường Trái Đất mạnh hơn từ trường kim nam châm, khi cân bằng, hai kim nam châm đó sẽ có dạng như</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c08.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ trường Trái Đất mạnh hơn nên cả hai kim đều bị định hướng theo hướng Nam – Bắc của Trái Đất: cực Bắc của mỗi kim chỉ về phía Bắc, tức hai kim xếp thành S–N, S–N như hình 1. Cách xếp này đồng thời cho cực Bắc kim này hướng về cực Nam kim kia nên hai kim hút nhau, cân bằng bền.</p>"}}]},{"id":656,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":1,"options":["hình 4.","hình 3.","hình 2.","hình 1."],"question":"<p>Hai kim nam châm nhỏ đặt xa các dòng điện và các nam châm khác; đường nối hai trọng tâm của chúng nằm theo hướng Nam – Bắc. Khi cân bằng, hướng của hai kim nam châm đó sẽ như</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c11.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai kim nam châm chỉ tương tác với nhau nên khi cân bằng, cực Bắc của kim này hướng về cực Nam của kim kia (các cực khác tên hút nhau) như hình 3.</p>","difficultySource":null},"ex":[{"exam":19,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":1,"options":["hình 4.","hình 3.","hình 2.","hình 1."],"question":"<p>Hai kim nam châm nhỏ đặt xa các dòng điện và các nam châm khác; đường nối hai trọng tâm của chúng nằm theo hướng Nam – Bắc. Khi cân bằng, hướng của hai kim nam châm đó sẽ như</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c11.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai kim nam châm chỉ tương tác với nhau nên khi cân bằng, cực Bắc của kim này hướng về cực Nam của kim kia (các cực khác tên hút nhau) như hình 3.</p>"}}]},{"id":671,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các đường thẳng từ trái qua phải.","Các đường thẳng từ phải qua trái.","Các vòng tròn theo chiều kim đồng hồ.","Các vòng tròn ngược chiều kim đồng hồ."],"question":"<p>Các đường sức từ xung quanh một dây dẫn thẳng dài mang dòng điện (Hình 3.2) có hình dạng nào sau đây?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c26.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng quy tắc nắm tay phải: ngón cái chỉ theo chiều dòng điện (hướng lên), các ngón còn lại khum lại cho chiều đường sức từ. Nhìn từ phía trên xuống mặt phẳng, các đường sức từ là những vòng tròn ngược chiều kim đồng hồ.</p>","difficultySource":null},"ex":[{"exam":19,"idx":25,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các đường thẳng từ trái qua phải.","Các đường thẳng từ phải qua trái.","Các vòng tròn theo chiều kim đồng hồ.","Các vòng tròn ngược chiều kim đồng hồ."],"question":"<p>Các đường sức từ xung quanh một dây dẫn thẳng dài mang dòng điện (Hình 3.2) có hình dạng nào sau đây?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/bt-c26.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng quy tắc nắm tay phải: ngón cái chỉ theo chiều dòng điện (hướng lên), các ngón còn lại khum lại cho chiều đường sức từ. Nhìn từ phía trên xuống mặt phẳng, các đường sức từ là những vòng tròn ngược chiều kim đồng hồ.</p>"}}]},{"id":710,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các mạt sắt xung quanh nam châm được sắp xếp thành những đường cong","Các đường cong này nối từ cực này sang cực kia của thanh nam châm","Các mạt sắt được sắp xếp dày hơn ở hai cực nam châm","Dùng mạt sắt hay mạt nhôm thì từ phổ đều có dạng giống nhau."],"question":"<p>Chọn phát biểu sai khi mô tả từ phổ của một nam châm thẳng</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c28.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ phổ chỉ tạo được bằng mạt sắt (vật liệu từ, bị từ hoá và sắp xếp theo đường sức). Mạt nhôm không bị từ hoá nên không tạo thành từ phổ.</p>","difficultySource":null},"ex":[{"exam":20,"idx":27,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các mạt sắt xung quanh nam châm được sắp xếp thành những đường cong","Các đường cong này nối từ cực này sang cực kia của thanh nam châm","Các mạt sắt được sắp xếp dày hơn ở hai cực nam châm","Dùng mạt sắt hay mạt nhôm thì từ phổ đều có dạng giống nhau."],"question":"<p>Chọn phát biểu sai khi mô tả từ phổ của một nam châm thẳng</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c28.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ phổ chỉ tạo được bằng mạt sắt (vật liệu từ, bị từ hoá và sắp xếp theo đường sức). Mạt nhôm không bị từ hoá nên không tạo thành từ phổ.</p>"}}]},{"id":712,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["Hình 1.","Hình 2.","Hình 3.","Hình 4."],"question":"<p>Một học sinh dùng một la bàn nhỏ đặt phía trên một đoạn dây dẫn thẳng dài mang dòng điện để tìm hiểu về chiều đường sức của dòng điện thẳng. Hình vẽ mô tả bốn thử nghiệm của học sinh này với một đoạn dây dẫn có dòng điện chạy qua. Hình ảnh nào thể hiện hướng chính xác của kim la bàn?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c30.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Dòng điện thẳng gây từ trường có đường sức là các vòng tròn quanh dây; kim la bàn nằm cân bằng vuông góc với dây nên loại Hình 3, 4. Theo quy tắc nắm tay phải (ngón cái theo chiều $I$ sang phải), ở phía trên dây từ trường hướng về phía dưới hình nên cực Bắc (đỏ) của kim chỉ xuống: Hình 2.</p>","difficultySource":null},"ex":[{"exam":20,"idx":29,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["Hình 1.","Hình 2.","Hình 3.","Hình 4."],"question":"<p>Một học sinh dùng một la bàn nhỏ đặt phía trên một đoạn dây dẫn thẳng dài mang dòng điện để tìm hiểu về chiều đường sức của dòng điện thẳng. Hình vẽ mô tả bốn thử nghiệm của học sinh này với một đoạn dây dẫn có dòng điện chạy qua. Hình ảnh nào thể hiện hướng chính xác của kim la bàn?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c30.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Dòng điện thẳng gây từ trường có đường sức là các vòng tròn quanh dây; kim la bàn nằm cân bằng vuông góc với dây nên loại Hình 3, 4. Theo quy tắc nắm tay phải (ngón cái theo chiều $I$ sang phải), ở phía trên dây từ trường hướng về phía dưới hình nên cực Bắc (đỏ) của kim chỉ xuống: Hình 2.</p>"}}]},{"id":713,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["đi vào mặt phẳng.","đi ra khỏi mặt phẳng và vuông góc với mặt phẳng.","quay ngược chiều kim đồng hồ.","quay theo chiều kim đồng hồ."],"question":"<p>Một dây dẫn điện thẳng được đặt vuông góc với mặt phẳng như hình vẽ. Đường sức từ quay ngược chiều kim đồng hồ. Chiều của dòng điện là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c31.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo quy tắc nắm tay phải: khum các ngón tay theo chiều đường sức (ngược chiều kim đồng hồ khi nhìn từ trên xuống) thì ngón cái chỉ chiều dòng điện đi ra khỏi mặt phẳng, vuông góc với mặt phẳng, hướng về phía người quan sát.</p>","difficultySource":null},"ex":[{"exam":20,"idx":30,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["đi vào mặt phẳng.","đi ra khỏi mặt phẳng và vuông góc với mặt phẳng.","quay ngược chiều kim đồng hồ.","quay theo chiều kim đồng hồ."],"question":"<p>Một dây dẫn điện thẳng được đặt vuông góc với mặt phẳng như hình vẽ. Đường sức từ quay ngược chiều kim đồng hồ. Chiều của dòng điện là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c31.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo quy tắc nắm tay phải: khum các ngón tay theo chiều đường sức (ngược chiều kim đồng hồ khi nhìn từ trên xuống) thì ngón cái chỉ chiều dòng điện đi ra khỏi mặt phẳng, vuông góc với mặt phẳng, hướng về phía người quan sát.</p>"}}]},{"id":714,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["Các đường thẳng từ trái qua phải","Các đường thẳng từ phải qua trái","Các vòng tròn theo chiều kim đồng hồ.","Các vòng tròn ngược chiều kim đồng hồ"],"question":"<p>Các đường sức từ trong lòng ống dây có dòng điện không đổi chạy qua (hình bên) có hình dạng nào sau đây ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c32.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây, đường sức từ là những đường thẳng song song, cách đều. Dòng điện đi từ cực + (đầu phải) vào ống dây; áp dụng quy tắc nắm tay phải (các ngón khum theo chiều dòng điện trong các vòng dây) thì ngón cái chỉ từ trái sang phải, nên đường sức trong lòng ống hướng từ trái qua phải.</p>","difficultySource":null},"ex":[{"exam":20,"idx":31,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["Các đường thẳng từ trái qua phải","Các đường thẳng từ phải qua trái","Các vòng tròn theo chiều kim đồng hồ.","Các vòng tròn ngược chiều kim đồng hồ"],"question":"<p>Các đường sức từ trong lòng ống dây có dòng điện không đổi chạy qua (hình bên) có hình dạng nào sau đây ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c32.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Trong lòng ống dây, đường sức từ là những đường thẳng song song, cách đều. Dòng điện đi từ cực + (đầu phải) vào ống dây; áp dụng quy tắc nắm tay phải (các ngón khum theo chiều dòng điện trong các vòng dây) thì ngón cái chỉ từ trái sang phải, nên đường sức trong lòng ống hướng từ trái qua phải.</p>"}}]},{"id":716,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["Hình 1","Hình 2","Hình 3","Hình 4"],"question":"<p>Giả sử có một dây dẫn thẳng dài vô hạn có dòng điện chạy qua theo phương vuông góc với mặt phẳng giấy và có chiều từ trong ra ngoài như hình vẽ. Hình nào dưới đây mô tả đúng đường sức từ trên mặt phẳng giấy của dây dẫn đang xét?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c34.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng là các đường tròn đồng tâm nên loại Hình 2, 4. Dòng điện hướng từ trong ra ngoài (dấu chấm), theo quy tắc nắm tay phải các đường sức có chiều ngược chiều kim đồng hồ: Hình 1.</p>","difficultySource":null},"ex":[{"exam":20,"idx":33,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["Hình 1","Hình 2","Hình 3","Hình 4"],"question":"<p>Giả sử có một dây dẫn thẳng dài vô hạn có dòng điện chạy qua theo phương vuông góc với mặt phẳng giấy và có chiều từ trong ra ngoài như hình vẽ. Hình nào dưới đây mô tả đúng đường sức từ trên mặt phẳng giấy của dây dẫn đang xét?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c34.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng là các đường tròn đồng tâm nên loại Hình 2, 4. Dòng điện hướng từ trong ra ngoài (dấu chấm), theo quy tắc nắm tay phải các đường sức có chiều ngược chiều kim đồng hồ: Hình 1.</p>"}}]},{"id":717,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các đường thẳng từ trái qua phải","Các đường thẳng từ phải qua trái","Các vòng tròn theo chiều kim đồng hồ","Các vòng tròn ngược chiều kim đồng hồ"],"question":"<p>Các đường sức từ xung quanh một dây dẫn thẳng dài mang dòng điện I (hình bên) có hình dạng nào sau đây ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c35.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng là những vòng tròn nằm trong mặt phẳng vuông góc với dây. Ngón cái chỉ chiều dòng điện (hướng lên), các ngón khum lại chỉ chiều đường sức: nhìn từ trên xuống, các vòng tròn quay ngược chiều kim đồng hồ.</p>","difficultySource":null},"ex":[{"exam":20,"idx":34,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":3,"options":["Các đường thẳng từ trái qua phải","Các đường thẳng từ phải qua trái","Các vòng tròn theo chiều kim đồng hồ","Các vòng tròn ngược chiều kim đồng hồ"],"question":"<p>Các đường sức từ xung quanh một dây dẫn thẳng dài mang dòng điện I (hình bên) có hình dạng nào sau đây ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c35.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ của dòng điện thẳng là những vòng tròn nằm trong mặt phẳng vuông góc với dây. Ngón cái chỉ chiều dòng điện (hướng lên), các ngón khum lại chỉ chiều đường sức: nhìn từ trên xuống, các vòng tròn quay ngược chiều kim đồng hồ.</p>"}}]},{"id":718,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":2,"options":["Điểm 1","Điểm 2","Điểm 3","Điểm 4"],"question":"<p>Tại điểm nào có kí hiệu không đúng với chiều của từ trường tạo bởi dòng điện không đổi I chạy trong một vòng dây dẫn hình tròn nằm trên mặt phẳng (xem hình vẽ)?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c36.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Dòng điện trong vòng dây chạy theo chiều kim đồng hồ nên mặt ta nhìn là mặt Nam: từ trường bên trong vòng dây đi vào mặt phẳng hình vẽ ($\\otimes$), bên ngoài vòng dây đi ra ($\\odot$). Điểm 3 nằm trong vòng dây nhưng lại kí hiệu $\\odot$ nên sai.</p>","difficultySource":null},"ex":[{"exam":20,"idx":35,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":2,"options":["Điểm 1","Điểm 2","Điểm 3","Điểm 4"],"question":"<p>Tại điểm nào có kí hiệu không đúng với chiều của từ trường tạo bởi dòng điện không đổi I chạy trong một vòng dây dẫn hình tròn nằm trên mặt phẳng (xem hình vẽ)?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c36.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Dòng điện trong vòng dây chạy theo chiều kim đồng hồ nên mặt ta nhìn là mặt Nam: từ trường bên trong vòng dây đi vào mặt phẳng hình vẽ ($\\otimes$), bên ngoài vòng dây đi ra ($\\odot$). Điểm 3 nằm trong vòng dây nhưng lại kí hiệu $\\odot$ nên sai.</p>"}}]},{"id":721,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["Bị hút sang trái.","Bị đẩy sang phải.","vẫn đứng yên.","bị đẩy sang trái rồi bị đẩy sang phải."],"question":"<p>Cho sơ đồ mạch điện và kim nam châm được treo như hình. Khi đóng công tắc K thì kim nam châm sẽ</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c39.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đóng K, ống dây thành nam châm điện. Dòng điện đi từ cực dương của nguồn qua công tắc vào đầu trái ống dây; theo quy tắc nắm tay phải, ngón cái chỉ sang trái nên đầu trái là cực Bắc, đầu phải (gần kim) là cực Nam. Cực Nam này hút cực Bắc N của kim nam châm nên kim bị hút sang trái.</p>","difficultySource":null},"ex":[{"exam":20,"idx":38,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["Bị hút sang trái.","Bị đẩy sang phải.","vẫn đứng yên.","bị đẩy sang trái rồi bị đẩy sang phải."],"question":"<p>Cho sơ đồ mạch điện và kim nam châm được treo như hình. Khi đóng công tắc K thì kim nam châm sẽ</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c39.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đóng K, ống dây thành nam châm điện. Dòng điện đi từ cực dương của nguồn qua công tắc vào đầu trái ống dây; theo quy tắc nắm tay phải, ngón cái chỉ sang trái nên đầu trái là cực Bắc, đầu phải (gần kim) là cực Nam. Cực Nam này hút cực Bắc N của kim nam châm nên kim bị hút sang trái.</p>"}}]},{"id":722,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["Hình A.","Hình B.","Hình C.","Hình D."],"question":"<p>Sự sắp xếp kim nam châm ở hình nào sau đây là đúng ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c40.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cực Bắc (đỏ) của kim nam châm chỉ theo chiều đường sức từ: bị hút về cực S và bị đẩy ra xa cực N. Ở hình A, kim phía trên chỉ từ N (trái) sang S (phải), kim phía dưới chỉ từ N (phải) sang S (trái), hai kim bên sườn chỉ từ cực N về phía cực S của thanh kề bên nên tất cả đều hợp lí. Ba hình còn lại có ít nhất một kim ngược chiều đường sức.</p>","difficultySource":null},"ex":[{"exam":20,"idx":39,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["Hình A.","Hình B.","Hình C.","Hình D."],"question":"<p>Sự sắp xếp kim nam châm ở hình nào sau đây là đúng ?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c40.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cực Bắc (đỏ) của kim nam châm chỉ theo chiều đường sức từ: bị hút về cực S và bị đẩy ra xa cực N. Ở hình A, kim phía trên chỉ từ N (trái) sang S (phải), kim phía dưới chỉ từ N (phải) sang S (trái), hai kim bên sườn chỉ từ cực N về phía cực S của thanh kề bên nên tất cả đều hợp lí. Ba hình còn lại có ít nhất một kim ngược chiều đường sức.</p>"}}]},{"id":730,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["pháp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","tiếp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","pháp tuyến tại mỗi điểm tạo với hướng của từ trường một góc không đổi.","tiếp tuyến tại mọi điểm tạo với hướng của từ trường một góc không đổi."],"question":"<p>Các đường sức từ là các đường cong vẽ trong không gian có từ trường sao cho</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c48.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định nghĩa, đường sức từ là đường vẽ trong không gian có từ trường sao cho tiếp tuyến tại mỗi điểm có hướng trùng với hướng của từ trường tại điểm đó.</p>","difficultySource":null},"ex":[{"exam":20,"idx":47,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["pháp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","tiếp tuyến tại mọi điểm trùng với hướng của từ trường tại điểm đó.","pháp tuyến tại mỗi điểm tạo với hướng của từ trường một góc không đổi.","tiếp tuyến tại mọi điểm tạo với hướng của từ trường một góc không đổi."],"question":"<p>Các đường sức từ là các đường cong vẽ trong không gian có từ trường sao cho</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c48.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định nghĩa, đường sức từ là đường vẽ trong không gian có từ trường sao cho tiếp tuyến tại mỗi điểm có hướng trùng với hướng của từ trường tại điểm đó.</p>"}}]},{"id":732,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["hình ảnh của các đường mạt sắt cho ta hình ảnh của các đường sức từ của từ trường.","hình ảnh tương tác của hai nam châm với nhau","hình ảnh tương tác giữa dòng điện và nam châm.","hình ảnh tương tác của hai dòng điện chạy trong hai dây dẫn thẳng song song."],"question":"<p>Từ phổ là:</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c50.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ phổ là hình ảnh các đường mạt sắt sắp xếp trong từ trường, cho ta hình ảnh trực quan về đường sức từ.</p>","difficultySource":null},"ex":[{"exam":20,"idx":49,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["hình ảnh của các đường mạt sắt cho ta hình ảnh của các đường sức từ của từ trường.","hình ảnh tương tác của hai nam châm với nhau","hình ảnh tương tác giữa dòng điện và nam châm.","hình ảnh tương tác của hai dòng điện chạy trong hai dây dẫn thẳng song song."],"question":"<p>Từ phổ là:</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c50.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Từ phổ là hình ảnh các đường mạt sắt sắp xếp trong từ trường, cho ta hình ảnh trực quan về đường sức từ.</p>"}}]},{"id":735,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["(1)-(2)-(5)-(3)-(4).","(1)-(2)-(4)-(3)-(5).","(3)-(2)-(5)-(1)-(4).","(2)-(1)-(3)-(4)-(5)."],"question":"<p>(Liên trường Nghệ An lần 3) Để xác định hình dạng và hướng đường sức từ của một nam châm thẳng, một nhóm học sinh thực hiện thí nghiệm với bộ dụng cụ gồm: Thanh nam châm, mạt sắt, hộp mica có thành và đáy bằng nhựa trong, kim nam châm (hình bên). Họ đã tiến hành thí nghiệm với các bước sau: (1). Rải đều mạt sắt lên mặt trên của đáy hộp. (2). Đặt hộp lên một thanh nam châm rồi gõ nhẹ vào thành hộp. (3). Đặt kim nam châm lên một đường sức, xác định hướng của đường sức đó. (4). Quan sát sự sắp xếp mạt sắt ở đáy hộp. (5). Vẽ dạng và biểu diễn hướng của các đường sức từ. Trình tự sắp xếp các bước tiến hành trong thí nghiệm trên là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c52b.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Trình tự hợp lí: rải mạt sắt (1), đặt hộp lên nam châm và gõ nhẹ (2), quan sát mạt sắt sắp xếp (4), dùng kim nam châm xác định hướng đường sức (3), cuối cùng vẽ dạng và hướng đường sức (5).</p>","difficultySource":null},"ex":[{"exam":20,"idx":52,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":1,"options":["(1)-(2)-(5)-(3)-(4).","(1)-(2)-(4)-(3)-(5).","(3)-(2)-(5)-(1)-(4).","(2)-(1)-(3)-(4)-(5)."],"question":"<p>(Liên trường Nghệ An lần 3) Để xác định hình dạng và hướng đường sức từ của một nam châm thẳng, một nhóm học sinh thực hiện thí nghiệm với bộ dụng cụ gồm: Thanh nam châm, mạt sắt, hộp mica có thành và đáy bằng nhựa trong, kim nam châm (hình bên). Họ đã tiến hành thí nghiệm với các bước sau: (1). Rải đều mạt sắt lên mặt trên của đáy hộp. (2). Đặt hộp lên một thanh nam châm rồi gõ nhẹ vào thành hộp. (3). Đặt kim nam châm lên một đường sức, xác định hướng của đường sức đó. (4). Quan sát sự sắp xếp mạt sắt ở đáy hộp. (5). Vẽ dạng và biểu diễn hướng của các đường sức từ. Trình tự sắp xếp các bước tiến hành trong thí nghiệm trên là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c52b.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Trình tự hợp lí: rải mạt sắt (1), đặt hộp lên nam châm và gõ nhẹ (2), quan sát mạt sắt sắp xếp (4), dùng kim nam châm xác định hướng đường sức (3), cuối cùng vẽ dạng và hướng đường sức (5).</p>"}}]},{"id":736,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":3,"options":["\"đẩy\" và \"chuông\".","\"hút\" và \"nam châm điện\".","\"đẩy\" và \"thanh kim loại mềm\".","\"hút\" và \"chuông\"."],"question":"<p>(Nguyễn Khuyến – LTT lần 3) Hình bên là một mô hình về chuông điện. Nguyên tắc hoạt động của chuông điện là khi công tắc đóng, từ tính nam châm điện xuất hiện...(1)...thanh kim loại, từ đó búa gõ đập vào...(2)...phát ra âm thanh. Chỗ trống (1) và (2) lần lượt là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c53.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi đóng công tắc, nam châm điện có từ tính hút thanh kim loại, làm búa gõ đập vào chuông phát ra âm thanh; mạch bị hở, nam châm mất từ tính, thanh bật về và quá trình lặp lại.</p>","difficultySource":null},"ex":[{"exam":20,"idx":53,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":3,"options":["\"đẩy\" và \"chuông\".","\"hút\" và \"nam châm điện\".","\"đẩy\" và \"thanh kim loại mềm\".","\"hút\" và \"chuông\"."],"question":"<p>(Nguyễn Khuyến – LTT lần 3) Hình bên là một mô hình về chuông điện. Nguyên tắc hoạt động của chuông điện là khi công tắc đóng, từ tính nam châm điện xuất hiện...(1)...thanh kim loại, từ đó búa gõ đập vào...(2)...phát ra âm thanh. Chỗ trống (1) và (2) lần lượt là</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c53.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi đóng công tắc, nam châm điện có từ tính hút thanh kim loại, làm búa gõ đập vào chuông phát ra âm thanh; mạch bị hở, nam châm mất từ tính, thanh bật về và quá trình lặp lại.</p>"}}]},{"id":737,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["xung quanh dây dẫn khi có dòng điện tồn tại từ trường.","dòng điện chạy trong dây dẫn đã làm mất từ tính của kim nam châm.","dòng điện chạy trong dây dẫn tác dụng lực điện làm lệch kim nam châm.","kim nam châm bị tích điện khi đặt gần dây dẫn có dòng điện."],"question":"<p>(Sở Nam Định) Một học sinh thực hiện thí nghiệm như sau. Đặt một kim nam châm nhỏ phía dưới một đoạn dây dẫn điện, ban đầu khi chưa có dòng điện chạy qua dây dẫn thì thấy kim nam châm nằm song song với sợi dây (Hình 1). Khi cho dòng điện không đổi chạy qua dây dẫn thì thấy kim nam châm quay tới vị trí cân bằng mới (Hình 2). Thí nghiệm trên chứng tỏ</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c54.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi có dòng điện, kim nam châm quay tới vị trí cân bằng mới chứng tỏ có lực từ tác dụng lên kim, tức xung quanh dây dẫn có dòng điện tồn tại từ trường (thí nghiệm Oersted).</p>","difficultySource":null},"ex":[{"exam":20,"idx":54,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Từ trường của nam châm và của dòng điện","answer":0,"options":["xung quanh dây dẫn khi có dòng điện tồn tại từ trường.","dòng điện chạy trong dây dẫn đã làm mất từ tính của kim nam châm.","dòng điện chạy trong dây dẫn tác dụng lực điện làm lệch kim nam châm.","kim nam châm bị tích điện khi đặt gần dây dẫn có dòng điện."],"question":"<p>(Sở Nam Định) Một học sinh thực hiện thí nghiệm như sau. Đặt một kim nam châm nhỏ phía dưới một đoạn dây dẫn điện, ban đầu khi chưa có dòng điện chạy qua dây dẫn thì thấy kim nam châm nằm song song với sợi dây (Hình 1). Khi cho dòng điện không đổi chạy qua dây dẫn thì thấy kim nam châm quay tới vị trí cân bằng mới (Hình 2). Thí nghiệm trên chứng tỏ</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c54.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi có dòng điện, kim nam châm quay tới vị trí cân bằng mới chứng tỏ có lực từ tác dụng lên kim, tức xung quanh dây dẫn có dòng điện tồn tại từ trường (thí nghiệm Oersted).</p>"}}]},{"id":738,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["(A) là cực Bắc và (B) là cực Nam.","Cả (A) và (B) đều là cực Bắc.","Cả (A) và (B) đều là cực Nam.","(A) là cực Nam và (B) là cực Bắc."],"question":"<p>(Sở Hà Nội) Hình dưới đây cho thấy các đường sức từ trường giữa hai cực từ (A) và (B). Nhận định nào sau đây mô tả đúng cực tính của các cực từ A và B?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c55.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ bên ngoài nam châm đi ra từ cực Bắc và đi vào cực Nam. Trên hình, các đường sức đi ra từ A và đi vào B nên A là cực Bắc, B là cực Nam.</p>","difficultySource":null},"ex":[{"exam":20,"idx":55,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đường sức từ và từ phổ","answer":0,"options":["(A) là cực Bắc và (B) là cực Nam.","Cả (A) và (B) đều là cực Bắc.","Cả (A) và (B) đều là cực Nam.","(A) là cực Nam và (B) là cực Bắc."],"question":"<p>(Sở Hà Nội) Hình dưới đây cho thấy các đường sức từ trường giữa hai cực từ (A) và (B). Nhận định nào sau đây mô tả đúng cực tính của các cực từ A và B?</p><img class=\"figure\" style=\"max-width:min(100%,680px);height:auto\" src=\"https://thachlab.id.vn/lessons/12-khai-niem-tu-truong/media/vn-c55.png\" alt=\"Hình minh họa\">","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Đường sức từ bên ngoài nam châm đi ra từ cực Bắc và đi vào cực Nam. Trên hình, các đường sức đi ra từ A và đi vào B nên A là cực Bắc, B là cực Nam.</p>"}}]},{"id":681140,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây dịch chuyển lại gần hay ra xa nam châm? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig66.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p>Nam châm nằm bên trái, cực N hướng vào vòng dây nên $\\vec{B}$ qua vòng hướng từ trái sang phải.</p>\n<p><strong>Hình 1</strong> ghi $I_{cx}=0$ khi vòng ra xa — sai: từ thông đang giảm nên vẫn có dòng cảm ứng. <strong>Hình 4</strong> ra xa nhưng chiều dòng không khớp định luật Len-xơ.</p>\n<p>Khi vòng <em>lại gần</em> (Hình 2 và 3): từ thông tăng $\\Rightarrow$ $\\vec{B}'$ ngược $\\vec{B}$ (sang trái, đối lại cực N). Quy tắc nắm tay phải cho chiều dòng như <strong>Hình 3</strong>.</p>\n<p><img class=\"figure\" src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/13/1790138214200-bai12-cam-ung-dien-tu-fig24.png\" alt=\"Hình 3: chiều dòng điện cảm ứng đúng\"></p>","distractorNotes":{"A":"Gắn $I_{cx}=0$ khi vòng ra xa: từ thông đang giảm nên vẫn phải có dòng cảm ứng.","B":"Đúng là vòng lại gần nhưng chiều dòng bị đảo (quy tắc nắm tay phải).","D":"Không khớp định luật Len-xơ khi từ thông giảm (vòng ra xa)."},"difficultySource":null},"ex":[{"exam":259,"idx":15,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Faraday và định luật Lenz","answer":2,"options":["Hình 1.","Hình 2.","Hình 3","Hình 4"],"question":"Hình vẽ nào sau đây xác định <strong>đúng</strong> chiều dòng điện cảm ứng khi cho vòng dây dịch chuyển lại gần hay ra xa nam châm? <img class=\"figure\" src=\"https://thachlab.id.vn/lessons/12-tu-thong-cam-ung-dien-tu/hinh/fig66.png\" alt=\"Hình minh họa\">","difficulty":"trung-binh","explanation":"<p>Nam châm nằm bên trái, cực N hướng vào vòng dây nên $\\vec{B}$ qua vòng hướng từ trái sang phải.</p>\n<p><strong>Hình 1</strong> ghi $I_{cx}=0$ khi vòng ra xa — sai: từ thông đang giảm nên vẫn có dòng cảm ứng. <strong>Hình 4</strong> ra xa nhưng chiều dòng không khớp định luật Len-xơ.</p>\n<p>Khi vòng <em>lại gần</em> (Hình 2 và 3): từ thông tăng $\\Rightarrow$ $\\vec{B}'$ ngược $\\vec{B}$ (sang trái, đối lại cực N). Quy tắc nắm tay phải cho chiều dòng như <strong>Hình 3</strong>.</p>\n<p><img class=\"figure\" src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/13/1790138214200-bai12-cam-ung-dien-tu-fig24.png\" alt=\"Hình 3: chiều dòng điện cảm ứng đúng\"></p>","distractorNotes":{"A":"Gắn $I_{cx}=0$ khi vòng ra xa: từ thông đang giảm nên vẫn phải có dòng cảm ứng.","B":"Đúng là vòng lại gần nhưng chiều dòng bị đảo (quy tắc nắm tay phải).","D":"Không khớp định luật Len-xơ khi từ thông giảm (vòng ra xa)."}}}]}]$j$::jsonb) loop
    h := public.question_content_hash(r->'nq');
    if exists (select 1 from public.question_bank where content_hash = h and id <> (r->>'id')::bigint) then raise notice 'TRUNG %', r->>'id'; continue; end if;
    update public.question_bank set question = r->'nq', content_hash = h, updated_at = now() where id = (r->>'id')::bigint;
    for e in select * from jsonb_array_elements(r->'ex') loop
      update public.exams set questions = jsonb_set(questions, array[e->>'idx'], e->'el') where id = (e->>'exam')::bigint;
    end loop;
  end loop;
end $do$;
alter table public.exams enable trigger trg_exams_sync_bank;
commit;
